# -*- coding: utf-8 -*-


class MootdxException(Exception):
    """Base notifier exception. Catch this to catch all of :mod:`notifiers` errors"""

    def __init__(self, *args, **kwargs):
        """
        Looks for ``provider``, ``message`` and ``data`` in kwargs
        :param args: Exception arguments
        :param kwargs: Exception kwargs
        """
        self.provider = kwargs.get('provider')
        self.message = kwargs.get('message')
        self.data = kwargs.get('data')
        super().__init__(*args)

    def __repr__(self):
        return f'<MootdxException(provider={self.provider}, message={self.message}, data={self.data})>'


class MootdxValidationException(Exception):
    def __init__(self, *args, **kwargs):
        pass


class MootdxModuleNotFoundError(Exception):
    def __init__(self, *args, **kwargs):
        pass


class FileNeedRefresh(FileNotFoundError):
    pass

# -*- coding: utf-8 -*-
import hashlib
import platform
import time
from pathlib import Path

import pandas as pd

from mootdx.config import get_config_path  # noqa
from mootdx.consts import FREQUENCY  # noqa
from mootdx.consts import MARKET_BJ, MARKET_SH, MARKET_SZ
from mootdx.logger import logger

_MARKET_MAP = {MARKET_SZ: 'sz', MARKET_SH: 'sh', MARKET_BJ: 'bj'}


def get_stock_market(symbol='', string=False):
    """判断股票代码对应的证券市场

    :param symbol: 股票代码
    :param string: False 返回市场ID, True 返回市场缩写名称
    :return: 市场ID(整数) 或 市场缩写名称(字符串)
    """
    market = MARKET_SZ
    symbol = str(symbol).strip()

    if symbol.startswith(('5', '6', '9')):
        market = MARKET_SH

    if symbol.startswith(('4', '8')):
        market = MARKET_BJ

    if string:
        return _MARKET_MAP.get(market, 'sz')

    return market


def get_stock_markets(symbols):
    """批量获取股票市场

    :param symbols: 股票代码列表
    :return: 股票市场列表
    """
    if isinstance(symbols, str):
        symbols = [symbols]

    results = []
    for symbol in symbols:
        results.append(get_stock_market(symbol, string=True))

    return results


def get_frequency(frequency) -> int:
    """获取 K 线周期

    :param frequency: 周期, 支持整数或字符串
    :return: 周期对应的整数
    """
    if isinstance(frequency, int):
        return frequency

    frequency = str(frequency).strip().lower()

    if frequency.isdigit():
        return int(frequency)

    try:
        return FREQUENCY.index(frequency)
    except ValueError:
        return 9


def check_empty(value):
    """检查值是否为空

    :param value: 待检查的值
    :return: 是否为空
    """
    if value is None:
        return True

    if isinstance(value, pd.DataFrame):
        return value.empty

    if isinstance(value, (list, tuple, dict, str, set)):
        return len(value) == 0

    return False


def to_data(v, **kwargs):
    """将各种格式的数据转换为标准的 pandas DataFrame

    :param v: 输入数据
    :param kwargs: 关键字参数
    :return: 标准化后的 DataFrame
    """
    symbol = kwargs.get('symbol')
    adjust = kwargs.get('adjust')

    if check_empty(v):
        return pd.DataFrame()

    if isinstance(v, pd.DataFrame):
        result = v
    elif isinstance(v, dict):
        try:
            result = pd.DataFrame(v)
        except ValueError:
            result = pd.DataFrame([v])
    elif isinstance(v, (list, tuple)):
        try:
            result = pd.DataFrame(v)
        except Exception:  # noqa
            result = pd.DataFrame(list(v))
    else:
        result = pd.DataFrame([v])

    if adjust and symbol:
        try:
            from mootdx.utils.adjust import to_adjust

            result = to_adjust(result, symbol=symbol, adjust=adjust)
        except Exception as e:  # noqa
            logger.warning(f'复权处理失败: {e}')

    return result


def to_file(df, filename=None):
    """将 DataFrame 导出为各种格式的文件

    :param df: 待导出的 DataFrame
    :param filename: 输出文件名, 支持 csv, xlsx, xls, json, h5 等格式
    :return: 是否导出成功
    """
    if df is None or filename is None:
        return False

    if isinstance(df, (list, tuple, dict)):
        df = to_data(df)

    if not isinstance(df, pd.DataFrame):
        return False

    suffix = Path(filename).suffix.lower()

    try:
        if suffix == '.csv':
            df.to_csv(filename, encoding='utf-8')
        elif suffix in ('.xlsx', '.xls'):
            df.to_excel(filename)
        elif suffix == '.json':
            df.to_json(filename, orient='records', force_ascii=False)
        elif suffix in ('.h5', '.hdf', '.hdf5'):
            df.to_hdf(filename, key='data')
        elif suffix in ('.pkl', '.plk', '.pickle'):
            df.to_pickle(filename)
        else:
            df.to_csv(filename, encoding='utf-8')
    except Exception as e:  # noqa
        logger.error(f'导出文件失败: {e}')
        return False

    return True


def md5sum(downfile):
    """计算文件的 MD5 值

    :param downfile: 文件路径
    :return: MD5 值字符串, 文件不存在返回 None
    """
    if not Path(downfile).is_file():
        return None

    md5 = hashlib.md5()

    with open(downfile, 'rb') as f:
        for chunk in iter(lambda: f.read(1024 * 512), b''):
            md5.update(chunk)

    return md5.hexdigest()


def _get_pyver():
    """获取 Python 版本信息"""
    return platform.python_version()


def reporthook(downloaded, total_size):
    """下载进度报告

    :param downloaded: 已下载大小
    :param total_size: 总大小
    """
    if total_size:
        percent = downloaded * 100.0 / total_size
        percent = min(percent, 100)
        print(f'\r已下载: {percent:5.1f}%', end='', flush=True)


def timeit(func):
    """统计函数执行时间的装饰器"""
    from mootdx.utils.timer import timeit as _timeit

    return _timeit(func)


