# -*- coding: utf-8 -*-
import functools
import time
from datetime import datetime, timedelta
from typing import Optional, cast

import pandas as pd

try:
    from typing import Callable, ParamSpec, Protocol, TypeVar
except ImportError:  # pragma: no cover
    from typing_extensions import Callable, ParamSpec, Protocol, TypeVar

P = ParamSpec('P')

try:
    from typing import TypeAlias

    PandasFunc: TypeAlias = Callable[P, pd.DataFrame]
except ImportError:  # pragma: no cover
    PandasFunc = Callable[P, pd.DataFrame]


class LRUCacheWrapper(Protocol[P]):
    lifetime: timedelta
    expiration: datetime

    def __call__(self, *args: P.args, **kwargs: P.kwargs) -> pd.DataFrame:
        pass

    def clear(self):
        pass


def lru_cache(seconds: Optional[int] = None, maxsize: Optional[int] = None, typed: bool = True):
    """带过期时间的 LRU 缓存装饰器

    :param seconds: 缓存秒数
    :param maxsize: 缓存最大条数
    :param typed: 是否按类型缓存
    :return: 装饰器函数
    """

    def decorator(func: PandasFunc) -> PandasFunc:
        @functools.lru_cache(maxsize=maxsize, typed=typed)
        def time_aware_func(*args: P.args, ttl_hash=None, **kwargs: P.kwargs) -> pd.DataFrame:
            del ttl_hash
            return func(*args, **kwargs)

        @functools.wraps(func)
        def retrieve_cache(*args: P.args, **kwargs: P.kwargs) -> pd.DataFrame:
            ttl_hash = None

            if seconds:
                ttl_hash = int(time.time() / seconds)

            lru_func = time_aware_func
            return lru_func(*args, ttl_hash=ttl_hash, **kwargs)

        retrieve_cache.clear = time_aware_func.cache_clear  # type: ignore
        retrieve_cache.lifetime = timedelta(seconds=seconds or 0)  # type: ignore
        retrieve_cache.expiration = datetime.now() + timedelta(seconds=seconds or 0)  # type: ignore

        return cast(PandasFunc, retrieve_cache)

    return decorator

# -*- coding: utf-8 -*-
import threading
import time


class Timer(object):
    """简单的定时器封装"""

    def __init__(self, interval, function, args=None, kwargs=None):
        self.interval = interval
        self.function = function
        self.args = args or []
        self.kwargs = kwargs or {}
        self._timer = None

    def _run(self):
        self.function(*self.args, **self.kwargs)
        self.start()

    def start(self):
        self._timer = threading.Timer(self.interval, self._run)
        self._timer.daemon = True
        self._timer.start()

    def cancel(self):
        if self._timer is not None:
            self._timer.cancel()
            self._timer = None


def delay(seconds):
    """延时执行, 返回秒数"""
    time.sleep(seconds)
    return seconds

# -*- coding: utf-8 -*-
import datetime
import json
import time
from pathlib import Path

import pandas as pd
from tenacity import retry, stop_after_attempt, wait_fixed

from mootdx.cache import file_cache
from mootdx.config import get_config_path
from mootdx.logger import logger

JS_DECODE = (Path(__file__).parent / 'holiday.js').read_text(encoding='utf-8')


def return_last_value(retry_state):
    """返回最后一次调用尝试的结果

    :param retry_state: 重试状态
    :return: 最后一次调用尝试的结果
    """
    return retry_state.outcome.result()


def _eval_js_decode():
    """通过 mini-racer 执行 JS 获取节假日数据"""
    try:
        from py_mini_racer import py_mini_racer

        ctx = py_mini_racer.MiniRacer()
        result = ctx.eval(JS_DECODE)
        return json.loads(result)
    except Exception as e:  # noqa
        logger.warning(f'mini-racer 执行失败, 尝试直接解析: {e}')

    # 兜底: 直接在 Python 侧解析 JS 数据
    import re

    data = []
    for year, days, name in re.findall(r"add\('(\d{4})', \[([^\]]*)\], '([^']+)'\)", JS_DECODE):
        for day in re.findall(r"'([^']+)'", days):
            data.append({'date': f'{year}-{day}', 'name': name})

    return data


@file_cache(filepath=get_config_path('caches/holiday.plk'), refresh_time=3600 * 24)
def _holiday():
    """获取节假日原始数据"""
    data = _eval_js_decode()

    df = pd.DataFrame(data)
    if not df.empty:
        df['date'] = pd.to_datetime(df['date'])
        df = df.sort_values('date').reset_index(drop=True)

    return df


@retry(wait=wait_fixed(2), retry_error_callback=return_last_value, stop=stop_after_attempt(5))
def _holidays() -> pd.DataFrame:
    return _holiday()


def holidays() -> pd.DataFrame:
    """获取完整的节假日(交易日历)数据

    :return: 节假日数据 DataFrame
    """
    cache_file = get_config_path('caches/holidays.plk')

    @file_cache(filepath=cache_file, refresh_time=3600 * 24)
    @retry(wait=wait_fixed(2), retry_error_callback=return_last_value, stop=stop_after_attempt(5))
    def _holidays_inner() -> pd.DataFrame:
        return _holiday()

    try:
        df = _holidays_inner()
    except Exception as e:  # noqa
        logger.warning(f'获取节假日数据失败: {e}')
        df = _holiday()

    if df is None:
        df = pd.DataFrame()

    return df


def holiday_(date=None, format_=None, country=None):
    """判断指定日期是否为节假日

    :param date: 日期
    :param format_: 日期格式
    :param country: 国家
    :return: 是否为节假日
    """
    date = date or time.strftime('%Y-%m-%d')
    format_ = format_ or '%Y-%m-%d'

    timestamp = datetime.datetime.strptime(str(date), format_)

    if country:
        # 其他国家/地区: 以周末为休息日
        return timestamp.weekday() >= 5

    # 中国: 周末或法定节假日
    if timestamp.weekday() >= 5:
        return True

    df = holidays()

    if df.empty:
        return False

    return bool((df['date'] == pd.Timestamp(timestamp)).any())


def holiday(date=None, format_=None, country=None):
    """判断指定日期是否为法定节假日

    :param date: 日期
    :param format_: 日期格式
    :param country: 国家
    :return: 是否为节假日
    """
    return holiday_(date=date, format_=format_, country=country)


def holiday2(date: str = None) -> pd.DataFrame:
    """获取指定日期的节假日信息

    :param date: 日期
    :return: 节假日信息 DataFrame
    """
    df = holidays()

    if df.empty:
        return df

    if date is None:
        return df

    for format_ in ('%Y-%m-%d', '%Y%m%d', '%Y/%m/%d'):
        try:
            timestamp = datetime.datetime.strptime(str(date), format_)
            break
        except ValueError:
            timestamp = None

    if timestamp is None:
        return df

    result = df[df['date'] == pd.Timestamp(timestamp)]

    if result.empty:
        result = pd.DataFrame([{'date': pd.Timestamp(timestamp), 'name': '工作日'}])

    return result.reset_index(drop=True)

# -*- coding: utf-8 -*-
from pathlib import Path

import numpy as np
import pandas as pd

from mootdx.cache import file_cache
from mootdx.config import get_config_path
from mootdx.logger import logger


def get_xdxr(symbol):
    """从通达信服务器获取除权除息数据

    :param symbol: 股票代码
    :return: 除权除息数据 DataFrame, 未找到返回 None
    """

    @file_cache(filepath=Path(get_config_path(f'xdxr/{symbol}.plk')), refresh_time=3600 * 24)
    def _xdxr(symbol):
        from mootdx.quotes import Quotes

        client = Quotes.factory(market='std')
        xdxr = client.xdxr(symbol=symbol)
        client.close()

        if xdxr is None or (hasattr(xdxr, 'empty') and xdxr.empty):
            return pd.DataFrame()

        xdxr = xdxr.copy()
        xdxr['date'] = pd.to_datetime(xdxr['date'], errors='coerce')

        return xdxr.set_index(['date'])

    return _xdxr(symbol)


def to_adjust(temp_df, symbol=None, adjust=None):
    """对数据进行复权处理

    :param temp_df: 待复权数据
    :param symbol: 股票代码
    :param adjust: 复权类型 (qfq/前复权, hfq/后复权)
    :return: 复权后的数据 DataFrame
    """
    if temp_df is None or (hasattr(temp_df, 'empty') and temp_df.empty):
        return temp_df

    if not adjust or not symbol:
        return temp_df

    adjust_map = {'qfq': 'qfq', '前复权': 'qfq', '01': 'qfq', 'hfq': 'hfq', '后复权': 'hfq', '02': 'hfq'}
    method = adjust_map.get(str(adjust).lower())

    if not method:
        return temp_df

    try:
        from mootdx.tools.reversion import factor_reversion

        return factor_reversion(symbol=symbol, method=method, raw=temp_df)
    except Exception as e:  # noqa
        logger.warning(f'复权处理失败: {e}')
        return temp_df


def to_adjust2(temp_df, symbol=None, adjust=None):
    """对数据进行复权处理 (方式二)

    :param temp_df: 待复权数据
    :param symbol: 股票代码
    :param adjust: 复权类型
    :return: 复权后的数据 DataFrame
    """
    if temp_df is None or (hasattr(temp_df, 'empty') and temp_df.empty):
        return temp_df

    if not adjust or not symbol:
        return temp_df

    type_map = {'qfq': '01', '前复权': '01', 'hfq': '02', '后复权': '02'}
    type_ = type_map.get(str(adjust).lower(), str(adjust))

    try:
        from mootdx.tools.reversion import reversion

        return reversion(symbol=symbol, stock_data=temp_df, xdxr=None, type_=type_)
    except Exception as e:  # noqa
        logger.warning(f'复权处理失败: {e}')
        return temp_df

# -*- coding: utf-8 -*-
"""A compact demjson-compatible module.

Implements the public API surface used by mootdx: JSON/JSON5-ish
encoding and decoding, the UTF-32 codec helper, the ``helpers`` utility
class, position tracking, options handling and the ``jsonlint`` class.
"""
import codecs
import re
import struct
import sys
from collections import namedtuple

__version_info__ = namedtuple('version_info', ['major', 'minor', 'micro'])(2, 2, 4)
__version__ = '.'.join(str(x) for x in __version_info__)
__credits__ = 'Short of demjson'

ALLOW = 'allow'
WARN = 'warn'
FORBID = 'forbid'

STRICTNESS_STRICT = 'strict'
STRICTNESS_WARN = 'warn'
STRICTNESS_TOLERANT = 'tolerant'

NUMBER_AUTO = 'auto'
NUMBER_FLOAT = 'float'
NUMBER_DECIMAL = 'decimal'

NUMBER_FORMAT_DECIMAL = 'decimal'
NUMBER_FORMAT_HEX = 'hex'
NUMBER_FORMAT_LEGACYOCTAL = 'legacyoctal'
NUMBER_FORMAT_OCTAL = 'octal'
NUMBER_FORMAT_BINARY = 'binary'

SORT_NONE = 'none'
SORT_PRESERVE = 'preserve'
SORT_ALPHA = 'alpha'
SORT_ALPHA_CI = 'alpha_ci'
SORT_SMART = 'smart'


# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------

class JSONException(Exception):
    """Base class for all JSON-related exceptions."""
    pass


class JSONSkipHook(JSONException):
    """An exception to be raised by user-defined code within hook callbacks
    to indicate the callback does not want to handle the situation."""
    pass


class JSONStopProcessing(JSONException):
    """Can be raised by anyplace, including inside a hook function, to cause
    the entire encode or decode process to immediately stop with an error."""
    pass


class JSONAbort(JSONException):
    pass


class JSONError(JSONException):
    """Base class for all JSON-related errors."""

    severities = frozenset(['fatal', 'error', 'warning', 'info'])

    def __init__(self, message, *args, **kwargs):
        self.severity = 'error'
        self._position = None
        self.outer_position = None
        self.context_description = None
        for kw, val in list(kwargs.items()):
            if kw == 'severity':
                if val not in self.severities:
                    raise TypeError('%s given invalid severity %r' % (self.__class__.__name__, val))
                self.severity = val
            elif kw == 'position':
                self.position = val
            elif kw == 'outer_position':
                self.outer_position = val
            elif kw in ('context_description', 'context'):
                self.context_description = val
            else:
                raise TypeError('%s does not accept %r keyword argument' % (self.__class__.__name__, kw))
        super(JSONError, self).__init__(message, *args)
        self.message = message

    @property
    def position(self):
        return self._position

    @position.setter
    def position(self, pos):
        self._position = pos

    def __repr__(self):
        return '<%s: %s>' % (self.__class__.__name__, self.message)

    def pretty_description(self, show_positions=True, filename=None):
        parts = []
        if filename:
            parts.append(str(filename))
        if show_positions and self._position is not None:
            parts.append(str(self._position))
        parts.append('%s: %s' % (self.severity, self.message))
        return ': '.join(parts)


class JSONDecodeError(JSONError):
    """An exception class raised when a JSON decoding error (syntax error) occurs."""
    pass


class JSONDecodeHookError(JSONDecodeError):
    """An exception that occured within a decoder hook."""

    def __init__(self, hook_name, exc_info, encoded_obj, *args, **kwargs):
        self.hook_name = hook_name
        if not exc_info:
            exc_info = (None, None, None)
        exc_type, self.hook_exception, self.hook_traceback = exc_info
        self.object_type = type(encoded_obj)
        msg = 'Hook %s raised %r while decoding type <%s>' % (
            hook_name, self.hook_exception.__class__.__name__, self.object_type.__name__)
        if len(args) >= 1:
            msg += ': ' + args[0]
            args = args[1:]
        super(JSONDecodeHookError, self).__init__(msg, *args, **kwargs)


class JSONEncodeError(JSONError):
    """An exception class raised when a python object can not be encoded as a JSON string."""
    pass


class JSONEncodeHookError(JSONEncodeError):
    """An exception that occured within an encoder hook."""

    def __init__(self, hook_name, exc_info, encoded_obj, *args, **kwargs):
        self.hook_name = hook_name
        if not exc_info:
            exc_info = (None, None, None)
        exc_type, self.hook_exception, self.hook_traceback = exc_info
        self.object_type = type(encoded_obj)
        msg = 'Hook %s raised %r while encoding type <%s>' % (
            self.hook_name, self.hook_exception.__class__.__name__, self.object_type.__name__)
        if len(args) >= 1:
            msg += ': ' + args[0]
            args = args[1:]
        super(JSONEncodeHookError, self).__init__(msg, *args, **kwargs)


# ---------------------------------------------------------------------------
# Special values
# ---------------------------------------------------------------------------

class _undefined_class(object):
    """Represents the ECMAScript 'undefined' value."""
    __slots__ = []

    def __repr__(self):
        return 'undefined'

    def __str__(self):
        return 'undefined'

    def __bool__(self):
        return False


undefined = _undefined_class()


class json_int((1).__class__):  # Have to specify base this way to satisfy 2to3
    """A subclass of the Python int/long that remembers its format (hex, octal, etc)."""

    def __new__(cls, *args, **kwargs):
        number_format = kwargs.pop('number_format', NUMBER_FORMAT_DECIMAL)
        if kwargs:
            raise TypeError('json_int got unexpected keyword arguments: %r' % list(kwargs.keys()))
        obj = super(json_int, cls).__new__(cls, *args)
        obj._number_format = number_format
        return obj

    @property
    def number_format(self):
        """The original radix format of the number"""
        return getattr(self, '_number_format', NUMBER_FORMAT_DECIMAL)

    def json_format(self):
        """Returns the integer value formatted as a JSON literal"""
        if self._number_format == NUMBER_FORMAT_HEX:
            return '0x%x' % self
        elif self._number_format in (NUMBER_FORMAT_OCTAL, NUMBER_FORMAT_LEGACYOCTAL):
            return '0o%o' % self if self._number_format == NUMBER_FORMAT_OCTAL else '0%o' % self
        elif self._number_format == NUMBER_FORMAT_BINARY:
            return '0b%s' % bin(self)[2:]
        return str(int(self))


# ---------------------------------------------------------------------------
# Numeric helpers
# ---------------------------------------------------------------------------

_float_limits = namedtuple('float_limits', ['significant_digits', 'max_exponent', 'min_exponent'])


def determine_float_limits(number_type=float):
    """Determines the precision and range of the given float type."""
    import decimal
    import math

    if number_type is float:
        info = sys.float_info
        return _float_limits(info.dig, int(math.log10(info.max)), int(math.log10(info.min)))
    if number_type is decimal.Decimal:
        ctx = decimal.getcontext()
        return _float_limits(ctx.prec, ctx.Emax, ctx.Emin)
    if isinstance(number_type, decimal.Context):
        return _float_limits(number_type.prec, number_type.Emax, number_type.Emin)
    raise TypeError('Unsupported number type %r' % (number_type,))


def determine_float_precision():
    """Determine the precision of the default float type."""
    limits = determine_float_limits(float)
    return (limits.significant_digits, limits.max_exponent, limits.min_exponent)


def _nonnumber_float_constants():
    """Try to return the Nan, Infinity, and -Infinity float values."""
    try:
        nan = float('nan')
        inf = float('inf')
        neginf = float('-inf')
        return nan, inf, neginf
    except Exception:  # pragma: no cover
        pass

    class _NonNumber(float):
        def __new__(cls, name):
            obj = super(_NonNumber, cls).__new__(cls, 0.0)
            obj._name = name
            return obj

        def __repr__(self):
            return self._name

    return _NonNumber('NaN'), _NonNumber('Infinity'), _NonNumber('-Infinity')


# ---------------------------------------------------------------------------
# String/list helpers
# ---------------------------------------------------------------------------

def skipstringsafe(s, start=0, end=None):
    """Skip string safe function."""
    if end is None:
        end = len(s)
    if start < 0:
        start = max(0, len(s) + start)
    return s[start:end]


def skipstringsafe_slow(s, start=0, end=None):
    """Skip string safe slow function."""
    if end is None:
        end = len(s)
    result = []
    i = start
    while i < end and i < len(s):
        result.append(s[i])
        i += 1
    return ''.join(result)


def extend_list_with_sep(orig_seq, extension_seq, sepchar=''):
    """Extend list with separator."""
    if not orig_seq:
        orig_seq.extend(extension_seq)
        return None
    for i, item in enumerate(extension_seq):
        if sepchar:
            orig_seq.append(sepchar)
        orig_seq.append(item)
    return None


def extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator=''):
    """Extend and flatten list with separator."""
    for i, item in enumerate(extension_seq):
        if i > 0 and separator:
            orig_seq.append(separator)
        if isinstance(item, (list, tuple)):
            orig_seq.extend(item)
        else:
            orig_seq.append(item)
    return None


def _make_raw_bytes(byte_list):
    """Takes a list of byte values (numbers) and returns a bytes (Python 3) or string (Python 2)"""
    return bytes(bytearray(byte_list))


def _make_unsafe_string_chars():
    """Make unsafe string chars."""
    unsafe = [chr(c) for c in range(0x20)]
    unsafe.extend(['"', "'", '\\'])
    return ''.join(unsafe)


def smart_sort_transform(key):
    """Smart sort transform: splits a string into text/number chunks for natural sorting."""
    parts = re.split(r'(\d+)', str(key))
    return [int(p) if p.isdigit() else p.lower() for p in parts]


# ---------------------------------------------------------------------------
# UTF-32 codec
# ---------------------------------------------------------------------------

class utf32(codecs.CodecInfo):
    """Unicode UTF-32 and UCS4 encoding/decoding support."""

    BOM_UTF32_BE = _make_raw_bytes([0, 0, 0xFE, 0xFF])
    BOM_UTF32_LE = _make_raw_bytes([0xFF, 0xFE, 0, 0])

    @staticmethod
    def lookup(name):
        """A standard Python codec lookup function for UCS4/UTF32."""
        normalized = name.replace('_', '-').lower()
        if normalized in ('utf32', 'utf-32', 'ucs4', 'ucs-4', 'utf32le', 'utf-32le', 'utf32be', 'utf-32be'):
            return codecs.lookup('utf-32')
        return None

    @staticmethod
    def encode(obj, errors='strict', endianness=None, include_bom=True):
        """Encodes a Unicode string into a UTF-32 encoded byte string."""
        if endianness is None:
            endianness = 'L' if sys.byteorder == 'little' else 'B'
        little = str(endianness).upper().startswith(('L', '<'))
        fmt = '<' if little else '>'
        out = bytearray()
        if include_bom:
            out += utf32.BOM_UTF32_LE if little else utf32.BOM_UTF32_BE
        for ch in obj:
            try:
                out += struct.pack(fmt + 'I', ord(ch))
            except struct.error:
                if errors == 'ignore':
                    continue
                if errors == 'replace':
                    out += struct.pack(fmt + 'I', 0xFFFD)
                    continue
                raise
        return bytes(out), len(obj)

    @staticmethod
    def utf32le_encode(obj, errors='strict', include_bom=False):
        """Encodes a Unicode string into a UTF-32LE (little endian) encoded byte string."""
        return utf32.encode(obj, errors=errors, endianness='L', include_bom=include_bom)

    @staticmethod
    def utf32be_encode(obj, errors='strict', include_bom=False):
        """Encodes a Unicode string into a UTF-32BE (big endian) encoded byte string."""
        return utf32.encode(obj, errors=errors, endianness='B', include_bom=include_bom)

    @staticmethod
    def decode(obj, errors='strict', endianness=None):
        """Decodes a UTF-32 byte string into a Unicode string."""
        if isinstance(obj, str):
            obj = obj.encode('latin-1')
        data = bytes(obj)

        if data.startswith(utf32.BOM_UTF32_LE):
            little = True
            data = data[4:]
        elif data.startswith(utf32.BOM_UTF32_BE):
            little = False
            data = data[4:]
        elif endianness is not None:
            little = str(endianness).upper().startswith(('L', '<'))
        else:
            little = False

        fmt = '<' if little else '>'
        chars = []
        size = len(data) - (len(data) % 4)
        for i in range(0, size, 4):
            codepoint = struct.unpack(fmt + 'I', data[i:i + 4])[0]
            try:
                chars.append(chr(codepoint))
            except ValueError:
                if errors == 'ignore':
                    continue
                if errors == 'replace':
                    chars.append('�')
                    continue
                raise UnicodeDecodeError('utf32', data, i, i + 4, 'invalid codepoint')
        return ''.join(chars), size

    @staticmethod
    def utf32le_decode(obj, errors='strict'):
        """Decodes a UTF-32LE (little endian) byte string into a Unicode string."""
        return utf32.decode(obj, errors=errors, endianness='L')

    @staticmethod
    def utf32be_decode(obj, errors='strict'):
        """Decodes a UTF-32BE (big endian) byte string into a Unicode string."""
        return utf32.decode(obj, errors=errors, endianness='B')


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

class helpers(object):
    """A set of utility functions."""

    hexdigits = '0123456789ABCDEFabcdef'
    octaldigits = '01234567'
    unsafe_string_chars = _make_unsafe_string_chars()

    maxunicode = sys.maxunicode

    always_use_custom_codecs = False

    javascript_reserved_words = frozenset([
        'break', 'case', 'catch', 'class', 'const', 'continue',
        'debugger', 'default', 'delete', 'do', 'else', 'export',
        'extends', 'finally', 'for', 'function', 'if', 'import',
        'in', 'instanceof', 'let', 'new', 'return', 'super',
        'switch', 'this', 'throw', 'try', 'typeof', 'var', 'void',
        'while', 'with', 'yield',
        'enum', 'implements', 'interface', 'package',
        'private', 'protected', 'public', 'static',
        'null', 'true', 'false',
    ])

    @staticmethod
    def make_raw_bytes(byte_list):
        """Constructs a byte array from a list of byte values (0-255)."""
        return _make_raw_bytes(byte_list)

    @staticmethod
    def is_hex_digit(c):
        return c in helpers.hexdigits

    @staticmethod
    def is_octal_digit(c):
        return c in helpers.octaldigits

    @staticmethod
    def is_binary_digit(c):
        return c in '01'

    @staticmethod
    def char_is_json_ws(c):
        return c in ' \t\n\r'

    @staticmethod
    def safe_unichr(codepoint):
        return chr(codepoint)

    @staticmethod
    def char_is_unicode_ws(c):
        return c.isspace()

    @staticmethod
    def char_is_json_eol(c):
        return c in '\n\r'

    @staticmethod
    def char_is_unicode_eol(c):
        import unicodedata
        return c in '\n\r' or unicodedata.category(c) in ('Zl', 'Zp')

    @staticmethod
    def char_is_identifier_leader(c):
        return c.isalpha() or c in '_$'

    @staticmethod
    def char_is_identifier_tail(c):
        return c.isalnum() or c in '_$'

    @staticmethod
    def extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator=''):
        return extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator)

    @staticmethod
    def strip_format_control_chars(txt):
        """Filters out all Unicode format control characters from the string."""
        import unicodedata
        return ''.join(c for c in txt if unicodedata.category(c) != 'Cf')

    @staticmethod
    def lookup_codec(encoding):
        """Wrapper around codecs.lookup(). Returns None if codec not found."""
        try:
            return codecs.lookup(encoding)
        except (LookupError, TypeError):
            found = utf32.lookup(encoding) if encoding else None
            return found

    @staticmethod
    def auto_detect_encoding(s):
        """Takes a string (or byte array) and tries to determine the Unicode encoding it is in."""
        if isinstance(s, str):
            return 'utf-8'
        data = bytes(s[:4])
        if data.startswith(codecs.BOM_UTF8):
            return 'utf-8-sig'
        if data.startswith(utf32.BOM_UTF32_BE):
            return 'utf-32-be'
        if data.startswith(utf32.BOM_UTF32_LE):
            return 'utf-32-le'
        if data.startswith(codecs.BOM_UTF16_BE):
            return 'utf-16-be'
        if data.startswith(codecs.BOM_UTF16_LE):
            return 'utf-16-le'
        if len(data) >= 4:
            a, b = data[0], data[1]
            if a == 0 and b == 0:
                return 'utf-32-be'
            if a != 0 and b == 0:
                return 'utf-16-le'
            if a == 0 and b != 0:
                return 'utf-16-be'
        return 'utf-8'

    @staticmethod
    def unicode_decode(txt, encoding=None):
        """Takes a string (or byte array) and tries to convert it to a Unicode string."""
        result = namedtuple('unicode_decode_result', ['string', 'codec', 'bom'])
        if isinstance(txt, str):
            return result(txt, None, '')
        data = bytes(txt)
        if encoding in (None, 'auto'):
            encoding = helpers.auto_detect_encoding(data)
        codec = codecs.lookup(encoding)
        bom = ''
        for marker, enc in ((codecs.BOM_UTF8, 'utf-8'), (codecs.BOM_UTF16_BE, 'utf-16-be'),
                            (codecs.BOM_UTF16_LE, 'utf-16-le')):
            if data.startswith(marker):
                bom = marker
                data = data[len(marker):]
                codec = codecs.lookup(enc)
                break
        return result(data.decode(codec.name), codec, bom)

    @staticmethod
    def surrogate_pair_as_unicode(c1, c2):
        """Takes a pair of unicode surrogates and returns the equivalent unicode character."""
        n1, n2 = ord(c1), ord(c2)
        if not (0xD800 <= n1 <= 0xDBFF and 0xDC00 <= n2 <= 0xDFFF):
            raise ValueError('Not a surrogate pair')
        return chr(0x10000 + ((n1 - 0xD800) << 10) + (n2 - 0xDC00))

    @staticmethod
    def unicode_as_surrogate_pair(c):
        """Takes a single unicode character and returns a sequence of surrogate pairs."""
        n = ord(c)
        if n < 0x10000:
            return (c,)
        n -= 0x10000
        return (chr(0xD800 + (n >> 10)), chr(0xDC00 + (n & 0x3FF)))

    @staticmethod
    def make_surrogate_pair(codepoint):
        """Given a Unicode codepoint (int) returns a 2-tuple of surrogate codepoints."""
        if codepoint < 0x10000:
            return (codepoint,)
        n = codepoint - 0x10000
        return (0xD800 + (n >> 10), 0xDC00 + (n & 0x3FF))

    @staticmethod
    def isnumbertype(obj):
        import decimal
        return isinstance(obj, (int, float, decimal.Decimal)) and not isinstance(obj, bool)

    @staticmethod
    def is_negzero(n):
        import math
        return n == 0 and math.copysign(1, n) < 0

    @staticmethod
    def is_nan(n):
        return n != n

    @staticmethod
    def is_infinite(n):
        import math
        try:
            return math.isinf(n)
        except TypeError:
            return False

    @staticmethod
    def isstringtype(obj):
        return isinstance(obj, (str, bytes))

    @staticmethod
    def decode_hex(hexstring):
        """Decodes a hexadecimal string into it's integer value."""
        s = hexstring.lower()
        if s.startswith('0x'):
            s = s[2:]
        if not s or any(c not in helpers.hexdigits for c in s):
            raise ValueError('Invalid hexadecimal string: %r' % hexstring)
        return int(s, 16)

    @staticmethod
    def decode_octal(octalstring):
        """Decodes an octal string into it's integer value."""
        s = octalstring.lower()
        if s.startswith('0o'):
            s = s[2:]
        if not s or any(c not in helpers.octaldigits for c in s):
            raise ValueError('Invalid octal string: %r' % octalstring)
        return int(s, 8)

    @staticmethod
    def decode_binary(binarystring):
        """Decodes a binary string into it's integer value."""
        s = binarystring.lower()
        if s.startswith('0b'):
            s = s[2:]
        if not s or any(c not in '01' for c in s):
            raise ValueError('Invalid binary string: %r' % binarystring)
        return int(s, 2)

    @staticmethod
    def format_timedelta_iso(td):
        """Encodes a datetime.timedelta into ISO-8601 Time Period format."""
        total = int(td.total_seconds())
        days, rem = divmod(total, 86400)
        hours, rem = divmod(rem, 3600)
        minutes, seconds = divmod(rem, 60)
        result = 'P'
        if days:
            result += '%dD' % days
        if hours or minutes or seconds or not days:
            result += 'T%dH%dM%dS' % (hours, minutes, seconds)
        return result


# ---------------------------------------------------------------------------
# position_marker and buffered_stream
# ---------------------------------------------------------------------------

class position_marker(object):
    """A position marks a specific place in a text document."""

    def __init__(self, offset=0, line=1, column=0, text_after=None):
        self.__char_position = offset
        self.__line = line
        self.__column = column
        self.__text_after = text_after
        self.__at_end = False
        self.__last_was_cr = False

    @property
    def line(self):
        """The current line within the document, starts at 1."""
        return self.__line

    @property
    def column(self):
        """The current character column from the beginning of the document, starts at 0."""
        return self.__column

    @property
    def char_position(self):
        """The current character offset from the beginning of the document, starts at 0."""
        return self.__char_position

    @property
    def at_start(self):
        """Returns True if the position is at the start of the document."""
        return self.__char_position == 0

    @property
    def at_end(self):
        """Returns True if the position is at the end of the document."""
        return self.__at_end

    @at_end.setter
    def at_end(self, b):
        self.__at_end = bool(b)

    @property
    def text_after(self):
        """Returns a textual excerpt starting at the current position."""
        return self.__text_after

    @text_after.setter
    def text_after(self, value):
        self.__text_after = value

    def __repr__(self):
        return '<position line=%d col=%d offset=%d>' % (self.__line, self.__column, self.__char_position)

    def describe(self, show_text=True):
        """Returns a human-readable description of the position, in English."""
        desc = 'line %d, column %d, char %d' % (self.__line, self.__column, self.__char_position)
        if show_text and self.__text_after:
            desc += ': near %r' % self.__text_after[:20]
        return desc

    def __str__(self):
        """Same as the describe() function."""
        return self.describe()

    def copy(self):
        """Create a copy of the position object."""
        dup = position_marker(self.__char_position, self.__line, self.__column, self.__text_after)
        dup.__at_end = self.__at_end
        dup.__last_was_cr = self.__last_was_cr
        return dup

    def rewind(self):
        """Set the position to the start of the document."""
        self.__char_position = 0
        self.__line = 1
        self.__column = 0
        self.__at_end = False
        self.__last_was_cr = False

    def advance(self, s):
        """Advance the position from its current place according to the given string."""
        for c in s:
            if c == '\n':
                self.__line += 1
                self.__column = 0
                self.__last_was_cr = False
            elif c == '\r':
                if not self.__last_was_cr:
                    self.__line += 1
                self.__column = 0
                self.__last_was_cr = True
            else:
                self.__column += 1
                self.__last_was_cr = False
            self.__char_position += 1
        if self.__text_after is not None:
            self.__text_after = self.__text_after[len(s):]


class buffered_stream(object):
    """A helper class for the JSON parser."""

    def __init__(self, txt='', encoding=None):
        self.reset()
        self.set_text(txt, encoding)

    def reset(self):
        """Clears the state to nothing."""
        self._text = ''
        self._offset = 0
        self._codec = None
        self._bom = ''
        self._saved_position = None

    def save_position(self):
        self._saved_position = self._offset

    def clear_saved_position(self):
        self._saved_position = None

    def restore_position(self):
        if self._saved_position is not None:
            self._offset = self._saved_position

    def _find_codec(self, encoding):
        return helpers.lookup_codec(encoding)

    def set_text(self, txt, encoding=None):
        """Changes the input text document and rewinds the position to the start."""
        if isinstance(txt, (bytes, bytearray)):
            decoded = helpers.unicode_decode(bytes(txt), encoding)
            self._text = decoded.string
            self._codec = decoded.codec
            self._bom = decoded.bom
        else:
            self._text = txt or ''
            self._codec = self._find_codec(encoding) if encoding else None
            self._bom = ''
        self._offset = 0

    def __repr__(self):
        return '<buffered_stream offset=%d len=%d>' % (self._offset, len(self._text))

    def rewind(self):
        """Resets the position back to the start of the input text."""
        self._offset = 0

    @property
    def codec(self):
        """The codec object used to perform Unicode decoding, or None."""
        return self._codec

    @property
    def bom(self):
        """The Unicode Byte-Order Mark (BOM), if any."""
        return self._bom

    @property
    def cpos(self):
        """The current character offset from the start of the document."""
        return self._offset

    @property
    def position(self):
        """The current position (as a position_marker object). Returns a copy."""
        text_before = self._text[:self._offset]
        line = text_before.count('\n') + 1
        last_nl = text_before.rfind('\n')
        column = self._offset if last_nl < 0 else self._offset - last_nl - 1
        marker = position_marker(self._offset, line, column)
        marker.text_after = self._text[self._offset:self._offset + 40]
        marker.at_end = self.at_end
        return marker

    @property
    def at_start(self):
        return self._offset == 0

    @property
    def at_end(self):
        return self._offset >= len(self._text)

    def at_ws(self, allow_unicode_whitespace=True):
        """Returns True if the current position contains a white-space character."""
        c = self.peek()
        if not c:
            return False
        if helpers.char_is_json_ws(c):
            return True
        return allow_unicode_whitespace and helpers.char_is_unicode_ws(c)

    def at_eol(self, allow_unicode_eol=True):
        """Returns True if the current position contains an end-of-line control character."""
        c = self.peek()
        if not c:
            return False
        if helpers.char_is_json_eol(c):
            return True
        return allow_unicode_eol and helpers.char_is_unicode_eol(c)

    def peek(self, offset=0):
        """Returns the character at the current position, or at a given offset away."""
        pos = self._offset + offset
        if 0 <= pos < len(self._text):
            return self._text[pos]
        return ''

    def peekstr(self, span=1, offset=0):
        """Returns one or more characters starting at the current position."""
        pos = self._offset + offset
        if pos < 0:
            span += pos
            pos = 0
        if span <= 0 or pos >= len(self._text):
            return ''
        return self._text[pos:pos + span]

    @property
    def text_context(self, context_size=20):
        """A short human-readable textual excerpt of the document at the current position."""
        start = max(0, self._offset - context_size)
        end = min(len(self._text), self._offset + context_size)
        return self._text[start:end]

    def startswith(self, s):
        """Determines if the text at the current position starts with the given string."""
        return self._text.startswith(s, self._offset)

    def skip(self, span=1):
        """Advances the current position by one (or the given number) of characters."""
        old = self._offset
        self._offset = min(len(self._text), self._offset + max(0, span))
        return self._offset - old

    def skipuntil(self, testfn):
        """Advances the current position until a given predicate test function succeeds."""
        count = 0
        while not self.at_end and not testfn(self.peek()):
            self._offset += 1
            count += 1
        return count

    def skipwhile(self, testfn):
        """Advances the current position until a given predicate test function fails."""
        count = 0
        while not self.at_end and testfn(self.peek()):
            self._offset += 1
            count += 1
        return count

    def skip_to_next_line(self, allow_unicode_eol=True):
        """Advances the current position to the start of the next line."""
        while not self.at_end:
            c = self.peek()
            self._offset += 1
            if c == '\n':
                break
            if c == '\r':
                if self.peek() == '\n':
                    self._offset += 1
                break
        return None

    def skipws(self, allow_unicode_whitespace=True):
        """Advances the current position past all whitespace."""
        while not self.at_end and self.at_ws(allow_unicode_whitespace):
            self._offset += 1
        return None

    def pop(self):
        """Returns the character at the current position and advances to the next."""
        c = self.peek()
        if c:
            self._offset += 1
        return c

    def popstr(self, span=1, offset=0):
        """Returns a string of one or more characters and advances past the span."""
        s = self.peekstr(span=span, offset=offset)
        self._offset = min(len(self._text), self._offset + offset + len(s))
        return s

    def popif(self, testfn):
        """Just like pop(), but only if the predicate test function succeeds."""
        c = self.peek()
        if c and testfn(c):
            self._offset += 1
            return c
        return ''

    def pop_while_in(self, chars):
        """Pops a sequence of characters as long as each is in the given set."""
        return self.popwhile(lambda c: c in chars)

    def pop_identifier(self, match=None):
        """Pops the sequence of characters that match a JavaScript identifier."""
        if not helpers.char_is_identifier_leader(self.peek()):
            return ''
        ident = self.popwhile(helpers.char_is_identifier_tail)
        if match is not None and ident != match:
            return ''
        return ident

    def pop_if_startswith(self, s):
        """Pops the sequence of characters if they match the given string."""
        if self.startswith(s):
            self._offset += len(s)
            return s
        return ''

    def popwhile(self, testfn, maxchars=None):
        """Pops all characters as long as each passes the predicate test."""
        chars = []
        while not self.at_end and testfn(self.peek()):
            if maxchars is not None and len(chars) >= maxchars:
                break
            chars.append(self._text[self._offset])
            self._offset += 1
        return ''.join(chars)

    def popuntil(self, testfn, maxchars=None):
        """Just like popwhile() except the predicate returns True to stop."""
        chars = []
        while not self.at_end and not testfn(self.peek()):
            if maxchars is not None and len(chars) >= maxchars:
                break
            chars.append(self._text[self._offset])
            self._offset += 1
        return ''.join(chars)

    def __getitem__(self, index):
        """Returns the character at the given index relative to the current position."""
        if isinstance(index, slice):
            if index.step not in (None, 1):
                raise ValueError('Stride values other than 1 are not supported')
            start = self._offset + (index.start or 0)
            stop = len(self._text) if index.stop is None else self._offset + index.stop
            return self._text[max(0, start):min(len(self._text), stop)]
        pos = self._offset + index
        if 0 <= pos < len(self._text):
            return self._text[pos]
        return ''


