class encode_state(object):
    """An internal transient object used during JSON encoding."""

    def __init__(self, jsopts=None, parent=None):
        self.chunks = []
        if not parent:
            self.parent = None
            self.nest_level = 0
            self.options = jsopts
            self.escape_unicode_test = False
        else:
            self.parent = parent
            self.nest_level = parent.nest_level + 1
            self.escape_unicode_test = parent.escape_unicode_test
            self.options = parent.options

    def make_substate(self):
        return encode_state(parent=self)

    def join_substate(self, other_state):
        self.chunks.extend(other_state.chunks)

    def append(self, s):
        """Adds a string to the end of the current JSON document"""
        self.chunks.append(s)

    def combine(self):
        """Returns the accumulated string and resets the state to empty"""
        result = ''.join(self.chunks)
        self.chunks = []
        return result

    def __eq__(self, other_state):
        return isinstance(other_state, encode_state) and self.chunks == other_state.chunks

    def __lt__(self, other_state):
        return len(self.chunks) < len(other_state.chunks)


class decode_statistics(object):
    """An object that records various statistics about a decoded JSON document."""

    int8_max = 0x7f
    int8_min = -0x7f - 1
    int16_max = 0x7fff
    int16_min = -0x7fff - 1
    int32_max = 0x7fffffff
    int32_min = -0x7fffffff - 1
    int64_max = 0x7fffffffffffffff
    int64_min = -0x7fffffffffffffff - 1

    double_int_max = 2 ** 53 - 1
    double_int_min = -(2 ** 53 - 1)

    def __init__(self):
        self.max_depth = 0
        self.max_items_in_array = 0
        self.max_items_in_object = 0
        self.num_ints = 0
        self.num_ints_8bit = 0
        self.num_ints_16bit = 0
        self.num_ints_32bit = 0
        self.num_ints_53bit = 0
        self.num_ints_64bit = 0
        self.num_ints_long = 0
        self.num_negative_zero_ints = 0
        self.num_negative_zero_floats = 0
        self.num_floats = 0
        self.num_floats_decimal = 0
        self.num_strings = 0
        self.max_string_length = 0
        self.total_string_length = 0
        self.min_codepoint = None
        self.max_codepoint = None
        self.num_arrays = 0
        self.num_objects = 0
        self.num_bools = 0
        self.num_nulls = 0
        self.num_undefineds = 0
        self.num_nans = 0
        self.num_infinities = 0
        self.num_comments = 0
        self.num_identifiers = 0
        self.num_excess_whitespace = 0

    @property
    def num_infinites(self):
        """Misspelled 'num_infinities' for backwards compatibility"""
        return self.num_infinities

    def pretty_description(self, prefix=''):
        """Returns a formatted string with a summary of the statistics."""
        lines = [
            'max_depth: %d' % self.max_depth,
            'num_arrays: %d' % self.num_arrays,
            'num_objects: %d' % self.num_objects,
            'num_strings: %d' % self.num_strings,
            'num_ints: %d' % self.num_ints,
            'num_floats: %d' % self.num_floats,
            'num_bools: %d' % self.num_bools,
            'num_nulls: %d' % self.num_nulls,
            'num_undefineds: %d' % self.num_undefineds,
            'num_comments: %d' % self.num_comments,
        ]
        return '\n'.join(prefix + line for line in lines)


class decode_state(object):
    """An internal transient object used during JSON decoding."""

    def __init__(self, options=None):
        self.reset()
        self.options = options

    def reset(self):
        """Clears all errors, statistics, and input text."""
        self.errors = []
        self.stats = decode_statistics()
        self.stream = buffered_stream('')

    @property
    def should_stop(self):
        return self.has_fatal

    @property
    def has_errors(self):
        """Have any errors been seen already?"""
        return any(e.severity in ('fatal', 'error') for e in self.errors)

    @property
    def has_fatal(self):
        """Have any fatal errors been seen already?"""
        return any(e.severity == 'fatal' for e in self.errors)

    def set_input(self, txt, encoding=None):
        """Initialize the state by setting the input document text."""
        self.stream = buffered_stream(txt, encoding)

    def push_exception(self, exc):
        """Add an already-built exception to the error list."""
        self.errors.append(exc)

    def push_fatal(self, message, *args, **kwargs):
        """Create a fatal error."""
        kwargs['severity'] = 'fatal'
        self.__push_err(message, *args, **kwargs)

    def push_error(self, message, *args, **kwargs):
        """Create an error."""
        kwargs.setdefault('severity', 'error')
        self.__push_err(message, *args, **kwargs)

    def push_warning(self, message, *args, **kwargs):
        """Create a warning."""
        kwargs['severity'] = 'warning'
        self.__push_err(message, *args, **kwargs)

    def push_info(self, message, *args, **kwargs):
        """Create a informational message."""
        kwargs['severity'] = 'info'
        self.__push_err(message, *args, **kwargs)

    def push_cond(self, behavior_value, message, *args, **kwargs):
        """Creates an conditional error or warning message."""
        if behavior_value == FORBID:
            self.push_error(message, *args, **kwargs)
        elif behavior_value == WARN:
            self.push_warning(message, *args, **kwargs)

    def __push_err(self, message, *args, **kwargs):
        """Stores an error in the error list."""
        if 'position' not in kwargs:
            try:
                kwargs['position'] = self.stream.position
            except Exception:  # noqa
                pass
        self.errors.append(JSONDecodeError(message, *args, **kwargs))

    def update_depth_stats(self, **kwargs):
        depth = kwargs.get('depth', 0)
        self.stats.max_depth = max(self.stats.max_depth, depth)

    def update_string_stats(self, s, **kwargs):
        self.stats.num_strings += 1
        self.stats.max_string_length = max(self.stats.max_string_length, len(s))
        self.stats.total_string_length += len(s)
        for c in s:
            cp = ord(c)
            self.stats.min_codepoint = cp if self.stats.min_codepoint is None else min(self.stats.min_codepoint, cp)
            self.stats.max_codepoint = cp if self.stats.max_codepoint is None else max(self.stats.max_codepoint, cp)

    def update_negzero_int_stats(self, **kwargs):
        self.stats.num_negative_zero_ints += 1

    def update_negzero_float_stats(self, **kwargs):
        self.stats.num_negative_zero_floats += 1

    def update_float_stats(self, float_value, **kwargs):
        self.stats.num_floats += 1
        if helpers.is_nan(float_value):
            self.stats.num_nans += 1
        elif helpers.is_infinite(float_value):
            self.stats.num_infinities += 1

    def update_integer_stats(self, int_value, **kwargs):
        stats = self.stats
        stats.num_ints += 1
        if decode_statistics.int8_min <= int_value <= decode_statistics.int8_max:
            stats.num_ints_8bit += 1
        elif decode_statistics.int16_min <= int_value <= decode_statistics.int16_max:
            stats.num_ints_16bit += 1
        elif decode_statistics.int32_min <= int_value <= decode_statistics.int32_max:
            stats.num_ints_32bit += 1
        elif decode_statistics.double_int_min <= int_value <= decode_statistics.double_int_max:
            stats.num_ints_53bit += 1
        elif decode_statistics.int64_min <= int_value <= decode_statistics.int64_max:
            stats.num_ints_64bit += 1
        else:
            stats.num_ints_long += 1


