class _behaviors_metaclass(type):
    """Meta class used to establish a set of "behavior" options."""

    def __new__(cls, clsname, bases, attrs):
        behaviors = attrs.get('_behaviors', ())
        values = attrs.get('_behavior_values', ())

        def get_behavior(self, name):
            if name not in self._behavior_names():
                raise KeyError('Unknown behavior %r' % name)
            return getattr(self, '_behavior_' + name, ALLOW)

        def set_behavior(self, name, value):
            """Changes the value for a given behavior"""
            if name not in self._behavior_names():
                raise KeyError('Unknown behavior %r' % name)
            if value not in values:
                raise ValueError('Invalid value %r for behavior %r' % (value, name))
            setattr(self, '_behavior_' + name, value)

        def describe_behavior(self, name):
            for bname, doc in self._behaviors:
                if bname == name:
                    return doc
            raise KeyError('Unknown behavior %r' % name)

        attrs['get_behavior'] = get_behavior
        attrs['set_behavior'] = set_behavior
        attrs['describe_behavior'] = describe_behavior

        seen = set()
        for bname, doc in behaviors:
            if bname in seen:
                continue
            seen.add(bname)

            def make_prop(name):
                def getx(self):
                    return self.get_behavior(name)

                def setx(self, value):
                    self.set_behavior(name, value)

                return property(getx, setx)

            attrs[bname] = make_prop(bname)

        for v in values:
            def make_getbehaviorsfor(value):
                def getbehaviorsfor(self):
                    return set(n for n in self._behavior_names() if self.get_behavior(n) == value)

                return getbehaviorsfor

            attrs['%s_behaviors' % v] = property(make_getbehaviorsfor(v))

        @property
        def all_behaviors(self):
            """Returns the names of all known behaviors."""
            return set(self._behavior_names())

        attrs['all_behaviors'] = all_behaviors

        def set_all(self, value):
            """Changes all behaviors to have the given value."""
            for name in self._behavior_names():
                self.set_behavior(name, value)

        def is_all(self, value):
            """Determines if all the behaviors have the given value."""
            return all(self.get_behavior(n) == value for n in self._behavior_names())

        def behaviors_eq(self, other):
            """Determines if two options objects are equivalent."""
            return all(self.get_behavior(n) == other.get_behavior(n) for n in self._behavior_names())

        attrs['set_all'] = set_all
        attrs['is_all'] = is_all
        attrs['behaviors_eq'] = behaviors_eq

        return super(_behaviors_metaclass, cls).__new__(cls, clsname, bases, attrs)


class json_options(object, metaclass=_behaviors_metaclass):
    """Options to determine how strict the decoder or encoder should be."""

    _behavior_values = (ALLOW, WARN, FORBID)
    _behaviors = (
        ('all_numeric_signs', "Numbers may be prefixed by any '+' and '-', e.g., +4, -+-+77"),
        ('any_type_at_start', 'A JSON document may start with any type, not just arrays or objects'),
        ('comments', 'JavaScript comments, both /*...*/ and //... styles'),
        ('control_char_in_string', 'Strings may contain raw control characters without \\u-escaping'),
        ('hex_numbers', 'Hexadecimal numbers, e.g., 0x1f'),
        ('binary_numbers', 'Binary numbers, e.g., 0b1001'),
        ('octal_numbers', 'New-style octal numbers, e.g., 0o731'),
        ('initial_decimal_point', 'Floating-point numbers may start with a decimal point (no units digit)'),
        ('extended_unicode_escapes', 'Extended Unicode escape sequence \\u{..} for non-BMP characters'),
        ('js_string_escapes', 'All JavaScript character \\-escape sequences may be in strings'),
        ('leading_zeros', 'Numbers may have extra leading zeros'),
        ('non_numbers', 'Non-numbers may be used, such as NaN or Infinity'),
        ('nonescape_characters', "Unknown character \\-escape sequences stand for that character (\\Q -> 'Q')"),
        ('identifier_keys', 'JavaScript identifiers are converted to strings when used as object keys'),
        ('nonstring_keys', 'Value types other than strings (or identifiers) may be used as object keys'),
        ('omitted_array_elements', 'Arrays may have omitted/elided elements, e.g., [1,,3]'),
        ('single_quoted_strings', "Strings may be delimited with both double (\") and single (') quotation marks"),
        ('trailing_comma', 'A final comma may end the list of array or object members'),
        ('trailing_decimal_point', 'Floating-point number may end with a decimal point'),
        ('undefined_values', "The JavaScript 'undefined' value may be used"),
        ('format_control_chars', 'Unicode "format control characters" may appear in the input'),
        ('unicode_whitespace', 'Treat any Unicode whitespace character as valid whitespace'),
        ('duplicate_keys', 'Objects may have repeated keys'),
        ('zero_byte', 'Strings may contain U+0000'),
        ('bom', 'A JSON document may start with a Unicode BOM (Byte Order Mark)'),
        ('non_portable', 'Anything technically valid but likely to cause data portablibity issues'),
    )

    _plain_attrs = ('compactly', 'escape_unicode', 'sort_keys_method', 'indent_num_spaces',
                    'indent_tab_width', 'indent_limit', 'encode_namedtuple_as_object',
                    'encode_enum_as_value', 'leading_zero_radix_value', 'strictness_value')

    def _behavior_names(self):
        seen = []
        for name, doc in self._behaviors:
            if name not in seen:
                seen.append(name)
        return seen

    def reset_to_defaults(self):
        self.compactly = True
        self.escape_unicode = False
        self.sort_keys_method = SORT_NONE
        self.indent_num_spaces = 2
        self.indent_tab_width = 0
        self.indent_limit = None
        self.encode_enum_as_value = 'value'
        self.leading_zero_radix_value = 8
        self.strictness_value = STRICTNESS_TOLERANT
        for name in self._behavior_names():
            try:
                self.set_behavior(name, ALLOW)
            except (KeyError, ValueError):  # noqa
                pass

    def __init__(self, **kwargs):
        self.reset_to_defaults()
        strict = kwargs.pop('strict', None)
        compactly = kwargs.pop('compactly', None)
        escape_unicode = kwargs.pop('escape_unicode', None)

        if strict is not None:
            self.strictness = STRICTNESS_STRICT if strict else STRICTNESS_TOLERANT
        if compactly is not None:
            self.compactly = bool(compactly)
        if escape_unicode is not None:
            self.escape_unicode = escape_unicode

        for key, value in kwargs.items():
            if key in self._behavior_names():
                self.set_behavior(key, value)
            elif hasattr(self, key):
                setattr(self, key, value)
            else:
                raise TypeError('Unknown option %r' % key)

    def copy(self):
        """Returns a shallow copy of the options."""
        dup = json_options()
        dup.copy_from(self)
        return dup

    def copy_from(self, other):
        for attr in self._plain_attrs:
            if hasattr(other, attr):
                setattr(self, attr, getattr(other, attr))
        for name in self._behavior_names():
            try:
                self.set_behavior(name, other.get_behavior(name))
            except (KeyError, ValueError):  # noqa
                pass

    def spaces_to_next_indent_level(self, min_spaces=1, subtract=0):
        return max(min_spaces, self.indent_num_spaces - subtract)

    def indentation_for_level(self, level=0):
        """Returns a whitespace string used for indenting."""
        if self.indent_limit is not None:
            level = min(level, self.indent_limit)
        return ' ' * (self.indent_num_spaces * level)

    def set_indent(self, num_spaces, tab_width=0, limit=None):
        """Changes the indentation properties when outputting JSON in non-compact mode."""
        self.indent_num_spaces = num_spaces
        self.indent_tab_width = tab_width
        self.indent_limit = limit

    @property
    def sort_keys(self):
        """The method used to sort dictionary keys when encoding JSON"""
        return self.sort_keys_method

    @sort_keys.setter
    def sort_keys(self, method):
        if method not in (SORT_NONE, SORT_PRESERVE, SORT_ALPHA, SORT_ALPHA_CI, SORT_SMART):
            raise ValueError('Invalid sort_keys method %r' % (method,))
        self.sort_keys_method = method

    @property
    def encode_enum_as(self):
        """The strategy for encoding Python Enum values."""
        return self.encode_enum_as_value

    @encode_enum_as.setter
    def encode_enum_as(self, val):
        if val not in ('name', 'qname', 'value'):
            raise ValueError("encode_enum_as must be one of 'name','qname', or 'value'")
        self.encode_enum_as_value = val

    @property
    def zero_float(self):
        return 0.0

    @property
    def negzero_float(self):
        return -0.0

    @property
    def nan(self):
        return float('nan')

    @property
    def inf(self):
        return float('inf')

    @property
    def neginf(self):
        return float('-inf')

    def make_int(self, s, sign=None, number_format=NUMBER_FORMAT_DECIMAL):
        """Makes an integer value according to the current options."""
        if isinstance(s, int):
            value = s
        elif number_format == NUMBER_FORMAT_HEX:
            value = helpers.decode_hex(s)
        elif number_format in (NUMBER_FORMAT_OCTAL, NUMBER_FORMAT_LEGACYOCTAL):
            value = helpers.decode_octal(s)
        elif number_format == NUMBER_FORMAT_BINARY:
            value = helpers.decode_binary(s)
        else:
            value = int(s)
        if sign == '-':
            value = -value
        return value

    def make_decimal(self, s, sign='+'):
        """Converts a string into a decimal or float value."""
        import decimal
        value = decimal.Decimal(s)
        return -value if sign == '-' else value

    def make_float(self, s, sign='+'):
        """Converts a string into a float or decimal value."""
        value = float(s)
        return -value if sign == '-' else value

    @property
    def leading_zero_radix(self):
        """The radix to be used for numbers with leading zeros. 8 or 10"""
        return self.leading_zero_radix_value

    @leading_zero_radix.setter
    def leading_zero_radix(self, radix):
        if radix not in (8, 10):
            raise ValueError('leading_zero_radix must be 8 or 10')
        self.leading_zero_radix_value = radix

    @property
    def leading_zero_radix_as_word(self):
        return 'octal' if self.leading_zero_radix_value == 8 else 'decimal'

    def suppress_warnings(self):
        for name in self._behavior_names():
            try:
                if self.get_behavior(name) == WARN:
                    self.set_behavior(name, ALLOW)
            except (KeyError, ValueError):  # noqa
                pass

    @property
    def allow_or_warn_behaviors(self):
        """Returns the set of all behaviors that are not forbidden."""
        return set(n for n in self._behavior_names() if self.get_behavior(n) != FORBID)

    @property
    def strictness(self):
        return self.strictness_value

    @strictness.setter
    def strictness(self, strict):
        """Changes whether the options should be re-configured for strict JSON conformance."""
        self.strictness_value = strict
        if strict == STRICTNESS_STRICT:
            for name in self._behavior_names():
                try:
                    self.set_behavior(name, FORBID)
                except (KeyError, ValueError):  # noqa
                    pass
        elif strict == STRICTNESS_WARN:
            for name in self._behavior_names():
                try:
                    self.set_behavior(name, WARN)
                except (KeyError, ValueError):  # noqa
                    pass
        else:
            for name in self._behavior_names():
                try:
                    self.set_behavior(name, ALLOW)
                except (KeyError, ValueError):  # noqa
                    pass


