_STRING_ESCAPES = {
    '"': '\\"', '\\': '\\\\', '\b': '\\b', '\f': '\\f',
    '\n': '\\n', '\r': '\\r', '\t': '\\t',
}


def _encode_string(s, escape_unicode=False):
    parts = ['"']
    for c in s:
        if c in _STRING_ESCAPES:
            parts.append(_STRING_ESCAPES[c])
        elif ord(c) < 0x20:
            parts.append('\\u%04x' % ord(c))
        elif escape_unicode and ord(c) > 0x7E:
            parts.append('\\u%04x' % ord(c))
        else:
            parts.append(c)
    parts.append('"')
    return ''.join(parts)


def encode(obj, encoding=None, **kwargs):
    """Encode the given object into a JSON string.

    :param obj: Object to encode
    :return: A string containing the encoded object
    """
    import decimal
    import enum

    opts = json_options()
    escape_unicode = kwargs.get('escape_unicode', False)
    sort_keys = kwargs.get('sort_keys', SORT_NONE)

    def _encode(value):
        if value is None:
            return 'null'
        if value is undefined or isinstance(value, _undefined_class):
            return 'undefined'
        if value is True:
            return 'true'
        if value is False:
            return 'false'
        if isinstance(value, enum.Enum):
            return _encode(value.value)
        if isinstance(value, json_int):
            return value.json_format()
        if isinstance(value, int):
            return str(value)
        if isinstance(value, decimal.Decimal):
            return str(value)
        if isinstance(value, float):
            if helpers.is_nan(value):
                return 'NaN'
            if helpers.is_infinite(value):
                return 'Infinity' if value > 0 else '-Infinity'
            return repr(value)
        if isinstance(value, str):
            return _encode_string(value, escape_unicode)
        if isinstance(value, (list, tuple)):
            return '[' + ','.join(_encode(item) for item in value) + ']'
        if isinstance(value, dict):
            keys = list(value.keys())
            if sort_keys in (SORT_ALPHA, SORT_ALPHA_CI):
                keys = sorted(keys, key=lambda k: str(k).lower() if sort_keys == SORT_ALPHA_CI else str(k))
            elif sort_keys == SORT_SMART:
                keys = sorted(keys, key=smart_sort_transform)
            items = []
            for key in keys:
                items.append('%s:%s' % (_encode_string(str(key), escape_unicode), _encode(value[key])))
            return '{' + ','.join(items) + '}'
        raise JSONEncodeError('Cannot encode object of type %s' % type(value).__name__)

    return _encode(obj)


def encode_to_file(filename, obj, encoding='utf-8', overwrite=False, **kwargs):
    """Encodes a Python object into JSON and writes into the given file."""
    import os

    if os.path.exists(filename) and not overwrite:
        raise JSONEncodeError('File already exists: %r (use overwrite=True)' % filename)

    text = encode(obj, **kwargs)

    with open(filename, 'w', encoding=encoding) as f:
        f.write(text)

    return None


# ---------------------------------------------------------------------------
# Decoder (tolerant JSON / JavaScript literal parser)
# ---------------------------------------------------------------------------

class _Parser(object):
    def __init__(self, txt):
        self.stream = buffered_stream(txt)

    def error(self, message):
        raise JSONDecodeError(message, position=self.stream.position)

    def skip_trivia(self):
        while not self.stream.at_end:
            self.stream.skipws()
            if self.stream.startswith('//'):
                self.stream.skip_to_next_line()
            elif self.stream.startswith('/*'):
                end = self.stream._text.find('*/', self.stream.cpos + 2)
                if end < 0:
                    self.error('Unterminated comment')
                self.stream._offset = end + 2
            else:
                break

    def parse(self):
        self.skip_trivia()
        if self.stream.at_end:
            self.error('Empty document')
        value = self.parse_value()
        self.skip_trivia()
        if not self.stream.at_end:
            self.error('Unexpected trailing data')
        return value

    def parse_value(self):
        self.skip_trivia()
        c = self.stream.peek()

        if c == '{':
            return self.parse_object()
        if c == '[':
            return self.parse_array()
        if c in ('"', "'"):
            return self.parse_string()
        if c == '' :
            self.error('Unexpected end of input')
        if c.isdigit() or c in '+-.':
            return self.parse_number()

        ident = self.stream.pop_identifier()
        if ident == 'true':
            return True
        if ident == 'false':
            return False
        if ident == 'null':
            return None
        if ident == 'undefined':
            return undefined
        if ident == 'NaN':
            return float('nan')
        if ident == 'Infinity':
            return float('inf')
        if ident:
            return ident

        self.error('Unexpected character %r' % c)

    def parse_object(self):
        self.stream.pop()  # {
        result = {}
        self.skip_trivia()
        if self.stream.peek() == '}':
            self.stream.pop()
            return result

        while True:
            self.skip_trivia()
            c = self.stream.peek()

            if c in ('"', "'"):
                key = self.parse_string()
            else:
                key = self.stream.pop_identifier()
                if not key:
                    value = self.parse_value()
                    key = str(value)

            self.skip_trivia()
            if self.stream.peek() == ':':
                self.stream.pop()
            elif self.stream.peek() == '=':
                self.stream.pop()
                if self.stream.peek() == '>':
                    self.stream.pop()
            else:
                self.error('Expected ":" in object, got %r' % self.stream.peek())

            value = self.parse_value()
            result[key] = value

            self.skip_trivia()
            c = self.stream.peek()
            if c == ',':
                self.stream.pop()
                self.skip_trivia()
                if self.stream.peek() == '}':
                    self.stream.pop()
                    return result
                continue
            if c == '}':
                self.stream.pop()
                return result
            self.error('Expected "," or "}" in object, got %r' % c)

    def parse_array(self):
        self.stream.pop()  # [
        result = []
        self.skip_trivia()
        if self.stream.peek() == ']':
            self.stream.pop()
            return result

        while True:
            self.skip_trivia()
            c = self.stream.peek()
            if c == ',':
                result.append(undefined)
            elif c == ']':
                self.stream.pop()
                return result
            else:
                result.append(self.parse_value())

            self.skip_trivia()
            c = self.stream.peek()
            if c == ',':
                self.stream.pop()
                self.skip_trivia()
                if self.stream.peek() == ']':
                    self.stream.pop()
                    return result
                continue
            if c == ']':
                self.stream.pop()
                return result
            self.error('Expected "," or "]" in array, got %r' % c)

    _STRING_ESCAPES_MAP = {
        'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t',
        'v': '\v', '0': '\0', '"': '"', "'": "'", '\\': '\\', '/': '/',
    }

    def parse_string(self):
        quote = self.stream.pop()
        chars = []

        while not self.stream.at_end:
            c = self.stream.pop()
            if c == quote:
                return ''.join(chars)
            if c == '\\':
                esc = self.stream.pop()
                if esc == 'u':
                    if self.stream.peek() == '{':
                        self.stream.pop()
                        hexdigits = self.stream.popuntil(lambda ch: ch == '}')
                        self.stream.pop()
                        chars.append(chr(int(hexdigits, 16)))
                    else:
                        hexdigits = self.stream.popstr(4)
                        try:
                            chars.append(chr(int(hexdigits, 16)))
                        except ValueError:
                            self.error('Invalid \\u escape sequence')
                elif esc == 'x':
                    hexdigits = self.stream.popstr(2)
                    try:
                        chars.append(chr(int(hexdigits, 16)))
                    except ValueError:
                        self.error('Invalid \\x escape sequence')
                elif esc == '\n':
                    pass  # line continuation
                elif esc in self._STRING_ESCAPES_MAP:
                    chars.append(self._STRING_ESCAPES_MAP[esc])
                else:
                    chars.append(esc)
            else:
                chars.append(c)

        self.error('Unterminated string literal')

    def parse_number(self):
        stream = self.stream
        start = stream.cpos

        while stream.peek() in '+-':
            stream.pop()

        if stream.startswith('0x') or stream.startswith('0X'):
            stream.skip(2)
            digits = stream.popwhile(helpers.is_hex_digit)
            if not digits:
                self.error('Invalid hexadecimal number')
            value = json_int(int(digits, 16), number_format=NUMBER_FORMAT_HEX)
        elif stream.startswith('0b') or stream.startswith('0B'):
            stream.skip(2)
            digits = stream.popwhile(helpers.is_binary_digit)
            if not digits:
                self.error('Invalid binary number')
            value = json_int(int(digits, 2), number_format=NUMBER_FORMAT_BINARY)
        elif stream.startswith('0o') or stream.startswith('0O'):
            stream.skip(2)
            digits = stream.popwhile(helpers.is_octal_digit)
            if not digits:
                self.error('Invalid octal number')
            value = json_int(int(digits, 8), number_format=NUMBER_FORMAT_OCTAL)
        else:
            numstr = stream.popwhile(lambda c: c.isdigit() or c in '.eE+-')
            if not numstr or numstr in ('+', '-', '.'):
                stream._offset = start
                self.error('Invalid number')
            try:
                if any(c in numstr for c in '.eE'):
                    value = float(numstr)
                else:
                    value = int(numstr)
            except ValueError:
                stream._offset = start
                self.error('Invalid number %r' % numstr)

        text = stream._text[start:stream.cpos]
        if text.startswith('-') and isinstance(value, (int, float)):
            return -value
        if text.startswith('+'):
            return value
        if text.startswith('-') and isinstance(value, json_int):
            return -int(value)
        return value


def decode(txt, encoding=None, **kwargs):
    """Decodes a JSON document into a Python object.

    :param txt: The JSON document text
    :param encoding: Character encoding (for byte input)
    :return: The decoded Python object
    """
    if isinstance(txt, (bytes, bytearray)):
        decoded = helpers.unicode_decode(bytes(txt), encoding)
        txt = decoded.string

    txt = helpers.strip_format_control_chars(txt)

    if txt and txt[0] == '﻿':
        txt = txt[1:]

    parser = _Parser(txt)
    return parser.parse()


def decode_file(filename, encoding=None, **kwargs):
    """Decodes JSON found in the given file."""
    mode = 'rb' if encoding in (None, 'auto') else 'r'

    if mode == 'rb':
        with open(filename, 'rb') as f:
            data = f.read()
        return decode(data, encoding=encoding, **kwargs)

    with open(filename, 'r', encoding=encoding) as f:
        return decode(f.read(), **kwargs)


