# jsonlint
# ---------------------------------------------------------------------------

class jsonlint(object):
    """This class contains most of the logic for the "jsonlint" command."""

    SUCCESS_FAIL = 'E'
    SUCCESS_WARNING = 'W'
    SUCCESS_OK = 'OK'

    _jsonlint_usage = 'Usage: %(program_name)s [<options> ...] [--] inputfile.json ...'

    def __init__(self, program_name='jsonlint', stdin=None, stdout=None, stderr=None):
        """Create an instance of a "jsonlint" program."""
        import os

        self.program_path = program_name
        self.program_name = os.path.basename(program_name)
        self.stdin = stdin or sys.stdin
        self.stdout = stdout or sys.stdout
        self.stderr = stderr or sys.stderr

    @property
    def usage(self):
        """A multi-line string containing the program usage instructions."""
        return self._jsonlint_usage % {'program_name': self.program_name, 'sort_options_help': '',
                                       'homepage': 'http://deron.meranda.us/python/demjson/'}

    def _lintcheck_data(self, jsondata, verbose_fp=None, reformat=False, show_stats=False,
                        input_encoding=None, output_encoding=None, escape_unicode=True, pfx='',
                        jsonopts=None):
        try:
            obj = decode(jsondata, encoding=input_encoding)
        except JSONError as e:
            if verbose_fp:
                verbose_fp.write('%s%s\n' % (pfx, e.pretty_description()))
            return self.SUCCESS_FAIL, None

        if show_stats and verbose_fp:
            state = decode_state()
            verbose_fp.write('%s%s\n' % (pfx, state.stats.pretty_description()))

        if reformat:
            return self.SUCCESS_OK, encode(obj, escape_unicode=escape_unicode)

        return self.SUCCESS_OK, None

    def _lintcheck(self, filename, output_filename, verbose=False, reformat=False, show_stats=False,
                   input_encoding=None, output_encoding=None, escape_unicode=True, jsonopts=None):
        if filename == '-':
            data = self.stdin.read()
        else:
            with open(filename, 'rb') as f:
                data = f.read()

        status, formatted = self._lintcheck_data(
            data, verbose_fp=self.stderr if verbose else None, reformat=reformat,
            show_stats=show_stats, input_encoding=input_encoding,
            output_encoding=output_encoding, escape_unicode=escape_unicode,
            jsonopts=jsonopts)

        if formatted is not None:
            if output_filename:
                with open(output_filename, 'w', encoding=output_encoding or 'utf-8') as f:
                    f.write(formatted)
            else:
                self.stdout.write(formatted + '\n')

        return status

    def main(self, argv):
        """The main routine for program "jsonlint"."""
        import getopt

        try:
            opts, args = getopt.getopt(argv, 'vqsfFWsS', ['verbose', 'quiet', 'format',
                                                          'format-compactly', 'stats', 'output=',
                                                          'strict', 'nonstrict', 'tolerant'])
        except getopt.GetoptError as e:
            self.stderr.write('%s\n' % e)
            self.stderr.write(self.usage + '\n')
            return 2

        verbose = False
        reformat = False
        show_stats = False
        output = None

        for opt, val in opts:
            if opt in ('-v', '--verbose'):
                verbose = True
            elif opt in ('-f', '-F', '--format', '--format-compactly'):
                reformat = True
            elif opt == '--stats':
                show_stats = True
            elif opt in ('-o', '--output'):
                output = val

        if not args:
            args = ['-']

        failed = False
        for filename in args:
            status = self._lintcheck(filename, output, verbose=verbose, reformat=reformat,
                                     show_stats=show_stats)
            if status == self.SUCCESS_FAIL:
                failed = True
            elif verbose:
                self.stdout.write('%s: %s\n' % (filename, status))

        return 1 if failed else 0

# -*- coding: utf-8 -*-
from pathlib import Path

import pandas as pd

from mootdx.logger import logger
from mootdx.utils import to_data


class BaseParse:
    """基础解析类, 用于解析通达信板块文件和配置文件"""

    def __init__(self, tdxdir):  # noqa
        self.tdxdir = tdxdir  # noqa

    def parse(self, symbol=None, group=False, **kwargs):
        """解析板块文件

        :param symbol: 板块文件名
        :param group: 是否按板块分组
        :return: 板块数据 DataFrame, 未找到返回 None
        """
        if not symbol:
            return None

        path = Path(self.tdxdir, 'T0002', 'hq_cache', symbol)

        if not path.exists():
            logger.warning(f'板块文件不存在: {path}')
            return None

        result = self.__incon(str(path))

        if result is None:
            return None

        df = to_data(result)

        if df.empty:
            return df

        if group and 'blockname' in df.columns:
            return df.groupby('blockname').agg(list)

        return df

    def read_text(self, path):
        """读取文本文件内容

        :param path: 文件路径
        :return: 文件内容, 文件不存在返回 None
        """
        filename = Path(self.tdxdir, path)

        if not filename.exists():
            logger.warning(f'文件不存在: {filename}')
            return None

        content = filename.read_bytes()

        for encoding in ('gbk', 'utf-8', 'gb2312', 'latin-1'):
            try:
                return content.decode(encoding)
            except UnicodeDecodeError:
                continue

        return content.decode('gbk', errors='ignore')

    def __incon(self, path):  # noqa
        """解析通达信板块文件 (incon 格式)

        :param path: 文件路径
        :return: 解析后的数据列表, 失败返回 None
        """
        try:
            content = Path(path).read_bytes()
        except OSError as e:  # noqa
            logger.warning(f'读取文件失败: {e}')
            return None

        # 文本格式
        try:
            text = content.decode('gbk', errors='ignore')
        except Exception:  # noqa
            return None

        rows = []
        block_name = ''
        block_type = ''

        for line in text.splitlines():
            line = line.strip()

            if not line:
                continue

            parts = line.split('|')

            if len(parts) >= 3 and parts[0] in ('0', '1', '2'):
                # 格式: 市场|代码|名称|...
                rows.append({
                    'blockname': block_name,
                    'block_type': block_type,
                    'market': parts[0],
                    'code': parts[1],
                    'name': parts[2],
                })
            elif len(parts) == 1 and parts[0].isdigit() and len(parts[0]) == 7:
                rows.append({
                    'blockname': block_name,
                    'block_type': block_type,
                    'market': parts[0][0],
                    'code': parts[0][1:],
                    'name': '',
                })
            else:
                # 板块名称行, 格式: #名称 或 名称
                block_name = parts[0].lstrip('#')

        return rows

    def cfg(self, path):
        """解析通达信配置文件 (如 tdxhy.cfg)

        :param path: 文件路径
        :return: 配置数据 DataFrame, 失败返回 None
        """
        content = self.read_text(path)

        if content is None:
            return None

        rows = []

        for line in content.splitlines():
            line = line.strip().strip('#')

            if not line:
                continue

            rows.append(line.split('|'))

        if not rows:
            return pd.DataFrame()

        width = max(len(row) for row in rows)
        rows = [row + [''] * (width - len(row)) for row in rows]

        return pd.DataFrame(rows)

