class BaseQuotes(object):
    """行情基类"""

    client = None
    bestip = None
    server = None

    verbose = False
    timeout = 15

    def __init__(self, server=None, bestip: bool = False, timeout: int = None, **kwargs) -> None:
        self.server = server
        self.timeout = timeout or 15
        self.verbose = kwargs.get('verbose', False)

        self.multithread = kwargs.get('multithread', False)
        self.heartbeat = kwargs.get('heartbeat', False)
        self.auto_retry = kwargs.get('auto_retry', False)
        self.raise_exception = kwargs.get('raise_exception', False)

        if bestip:
            self.bestip = self.get_bestip()

        if self.server:
            self.connect(*self.server)
        elif self.bestip:
            self.connect(*self.bestip)

    def get_bestip(self):
        """获取最优服务器"""
        try:
            from mootdx.server import bestip

            return bestip(index=self.market_type, limit=1)
        except Exception as e:  # noqa
            logger.warning(f'获取最优服务器失败: {e}')
            return None

    def connect(self, ip, port, **kwargs):
        """连接服务器 (子类实现)"""
        raise NotImplementedError

    def __del__(self):
        try:
            self.close()
        except Exception:  # noqa
            pass

    def reconnect(self):
        """重新连接服务器"""
        try:
            self.close()
        except Exception:  # noqa
            pass

        if self.server:
            return self.connect(*self.server)
        if self.bestip:
            return self.connect(*self.bestip)

        return False

    def close(self):
        """关闭连接"""
        if self.client is not None:
            try:
                self.client.disconnect()
            except Exception as e:  # noqa
                logger.debug(f'关闭连接异常: {e}')

    @property
    def closed(self) -> bool:
        """连接是否已关闭"""
        if self.client is None:
            return True

        try:
            return not bool(self.client.client)
        except Exception:  # noqa
            return True

    def pool(self):
        """获取连接池"""
        return self.client


class StdQuotes(BaseQuotes):
    """标准股票市场行情类"""

    market_type = 'HQ'

    def __init__(self, server=None, bestip: bool = False, timeout: int = None, **kwargs) -> None:
        from tdxpy.hq import TdxHq_API

        self.client = TdxHq_API(
            multithread=kwargs.get('multithread', False),
            heartbeat=kwargs.get('heartbeat', False),
            auto_retry=kwargs.get('auto_retry', False),
            raise_exception=kwargs.get('raise_exception', False),
        )

        if server is None and not bestip:
            server = config.get('BESTIP', {}).get('HQ') or None
            if not server:
                from mootdx.consts import HQ_HOSTS

                server = (HQ_HOSTS[0][1], HQ_HOSTS[0][2])

        super().__init__(server=server, bestip=bestip, timeout=timeout, **kwargs)

    def connect(self, ip, port=7709, **kwargs):
        """连接服务器"""
        try:
            self.server = (ip, port)
            return self.client.connect(ip, port, time_out=self.timeout)
        except Exception as e:  # noqa
            logger.warning(f'连接服务器失败 {ip}:{port}: {e}')
            return False

    def quotes(self, symbol=None, **kwargs):
        """获取实时行情, 支持单个或多个股票代码

        :param symbol: 股票代码
        :return: 行情数据 DataFrame
        """
        if not symbol:
            return pd.DataFrame()

        if isinstance(symbol, str):
            symbol = [s.strip() for s in symbol.split(',') if s.strip()]

        symbols = [(get_stock_market(s), s) for s in symbol]

        try:
            data = self.client.get_security_quotes(symbols)
        except Exception as e:  # noqa
            logger.warning(f'获取行情失败: {e}')
            return pd.DataFrame()

        return to_data(data)

    def bars(self, symbol='600036', frequency=9, start=0, offset=100, adjust=None, **kwargs):
        """获取 K 线数据

        :param symbol: 股票代码
        :param frequency: K 线周期
        :param start: 开始位置
        :param offset: 数据条数
        :param adjust: 复权类型 (qfq/hfq)
        :return: K 线数据 DataFrame
        """
        frequency = get_frequency(frequency)
        market = get_stock_market(symbol)
        offset = min(int(offset), 800)

        try:
            data = self.client.get_security_bars(frequency, market, str(symbol), int(start), offset)
        except Exception as e:  # noqa
            logger.warning(f'获取K线数据失败: {e}')
            return pd.DataFrame()

        result = to_data(data)

        if adjust:
            from mootdx.utils.adjust import to_adjust

            result = to_adjust(result, symbol=symbol, adjust=adjust)

        return result

