            data = self.client.get_index_bars(frequency, int(market), str(symbol), int(start), int(offset))
        except Exception as e:  # noqa
            logger.warning(f'获取指数数据失败: {e}')
            return pd.DataFrame()

        return to_data(data)

    def minute(self, symbol='000001', **kwargs):
