        """获取市场证券列表

        :param market: 市场代码 (0: 深圳, 1: 上海)
        :return: 证券列表 DataFrame
        """
        if market not in (MARKET_SZ, MARKET_SH):
            raise MootdxValidationException('股票市场代码错误, 目前仅支持沪深市场')

        counts = self.stock_count(market=market)

