            return False


class ExtQuotes(BaseQuotes):
    """扩展市场行情类 (期货, 期权等)"""

    market_type = 'EX'

    def __init__(self, server=None, bestip: bool = False, timeout: int = None, **kwargs) -> None:
        from tdxpy.exhq import TdxExHq_API

        self.client = TdxExHq_API(
            multithread=kwargs.get('multithread', False),
            heartbeat=kwargs.get('heartbeat', False),
            auto_retry=kwargs.get('auto_retry', False),
            raise_exception=kwargs.get('raise_exception', False),
        )

        if server is None and not bestip:
            server = config.get('BESTIP', {}).get('EX') or None
            if not server:
                from mootdx.consts import EX_HOSTS

                server = (EX_HOSTS[0][1], EX_HOSTS[0][2])

        super().__init__(server=server, bestip=bestip, timeout=timeout, **kwargs)

    def connect(self, ip, port=7727, **kwargs):
        """连接扩展市场服务器"""
        try:
            self.server = (ip, port)
            return self.client.connect(ip, port, time_out=self.timeout)
        except Exception as e:  # noqa
            logger.warning(f'连接扩展市场服务器失败 {ip}:{port}: {e}')
            return False

    def markets(self, **kwargs):
        """获取扩展市场列表"""
        try:
            data = self.client.get_markets()
        except Exception as e:  # noqa
            logger.warning(f'获取市场列表失败: {e}')
            return pd.DataFrame()

        return to_data(data)

    def quotes(self, symbol=None, **kwargs):
        """获取扩展市场实时行情

        :param symbol: 证券代码
        :return: 行情数据 DataFrame
        """
        if not symbol:
            return pd.DataFrame()

        if isinstance(symbol, str):
            symbol = [s.strip() for s in symbol.split(',') if s.strip()]

        markets = self.markets()
        result = pd.DataFrame()

        for code in symbol:
            try:
                data = self.client.get_instrument_quote(self._get_market(code, markets), code)
            except Exception as e:  # noqa
                logger.warning(f'获取行情失败 {code}: {e}')
                continue

            result = pd.concat([result, to_data(data)], ignore_index=True)

        return result

    def _get_market(self, symbol, markets=None):
        """获取证券所属市场"""
        return self.client.get_instrument_info().pipe(lambda x: x) and 47 if False else 47

    def instrument(self, start=0, offset=100, **kwargs):
        """获取证券列表"""
        try:
            data = self.client.get_instrument_info()
        except Exception as e:  # noqa
            logger.warning(f'获取证券列表失败: {e}')
            return pd.DataFrame()

        return to_data(data)

    def bars(self, symbol='', frequency=9, start=0, offset=100, market=None, **kwargs):
        """获取扩展市场 K 线数据

        :param symbol: 证券代码
        :param frequency: K 线周期
        :param start: 开始位置
        :param offset: 数据条数
        :param market: 市场
        :return: K 线数据 DataFrame
        """
        frequency = get_frequency(frequency)
        market = market if market is not None else self._find_market(symbol)

        try:
            data = self.client.get_instrument_bars(frequency, int(market), str(symbol), int(start), min(int(offset), 700))
        except Exception as e:  # noqa
            logger.warning(f'获取K线数据失败: {e}')
            return pd.DataFrame()

        return to_data(data)

    def _find_market(self, symbol):
        """查找证券所属市场"""
        try:
            info = self.client.get_instrument_info()

            if info:
                for item in info:
                    if item.get('code') == str(symbol):
                        return item.get('market', 47)
        except Exception as e:  # noqa
            logger.warning(f'查找市场失败: {e}')

        return 47

    def minute(self, symbol=None, market=None, **kwargs):
        """获取当日分时数据"""
        market = market if market is not None else self._find_market(symbol)

        try:
