# -*- coding: utf-8 -*-
from abc import ABC
from pathlib import Path

import pandas as pd

from mootdx import config
from mootdx.logger import logger
from mootdx.utils import get_stock_market


class ReaderBase(ABC):
    """数据读取基类"""

    # 默认通达信安装目录
    tdxdir = 'C:/new_tdx'

    def __init__(self, tdxdir=None):
        if tdxdir:
            self.tdxdir = str(tdxdir)
        else:
            self.tdxdir = str(config.get('TDXDIR', self.tdxdir))

    def find_path(self, symbol=None, subdir='lday', suffix=None, **kwargs):
        """根据股票代码查找数据文件路径

        :param symbol: 股票代码
        :param subdir: 子目录名称, 默认 lday
        :param suffix: 文件后缀, 默认 None
        :return: 文件路径字符串, 未找到返回 None
        """
        if not symbol:
            return None

        market = get_stock_market(symbol, string=True)
        suffix = suffix or ['day']

        if isinstance(suffix, str):
            suffix = [suffix]

        vipdoc = Path(self.tdxdir, 'vipdoc')

        for ext in suffix:
            for mkt in {market, 'sh' if market == 'bj' else market, 'sz' if market == 'bj' else market}:
                filename = vipdoc / mkt / subdir / f'{mkt}{symbol}.{ext}'

                if filename.exists():
                    logger.debug(f'找到数据文件: {filename}')
                    return str(filename)

        logger.warning(f'未找到数据文件: {symbol} {subdir} {suffix}')
        return None


class StdReader(ReaderBase):
    """标准股票市场数据读取类"""

    def daily(self, symbol=None, **kwargs):
        """获取日线数据

        :param symbol: 股票代码
        :return: 日线数据 DataFrame, 未找到返回 None
        """
        reader = self._daily_reader()
        filename = self.find_path(symbol=symbol, subdir='lday', suffix='day')

        if filename is None:
            return None

        result = reader.get_df(filename)

        if kwargs.get('adjust'):
            from mootdx.utils.adjust import to_adjust

            result = to_adjust(result, symbol=symbol, adjust=kwargs.get('adjust'))

        return result

    def minute(self, symbol=None, suffix=1, **kwargs):  # noqa
        """获取分钟线数据

        :param symbol: 股票代码
        :param suffix: 文件后缀 (1: 1分钟线, 5: 5分钟线)
        :return: 分钟线数据 DataFrame, 未找到返回 None
        """
        subdir = 'minline'
        suffix = str(suffix).lstrip('.')
        suffixes = [f'lc{suffix}', suffix]

        filename = self.find_path(symbol=symbol, subdir=subdir, suffix=suffixes)

        if filename is None:
            return None

        if filename.endswith(('.lc1', '.lc5')):
            from tdxpy.reader import TdxLCMinBarReader

            return TdxLCMinBarReader().get_df(filename)

        from tdxpy.reader import TdxMinBarReader

        return TdxMinBarReader().get_df(filename)

    def fzline(self, symbol=None):
        """获取五分钟线数据

        :param symbol: 股票代码
        :return: 五分钟线数据 DataFrame, 未找到返回 None
        """
        return self.minute(symbol=symbol, suffix=5)

    def block_new(self, name: str = None, symbol: list = None, group=False, **kwargs):
        """获取自定义板块数据

        :param name: 板块名称
        :param symbol: 股票代码列表
        :param group: 是否分组
        :return: 板块数据 DataFrame, 未找到返回 None
        """
        from mootdx.tools.customize import Customize

        customize = Customize(tdxdir=self.tdxdir)

        if name and symbol is not None:
            customize.create(name=name, symbol=symbol, **kwargs)

        return customize.search(name=name, group=group)

    def block(self, symbol='', group=False, **kwargs):
        """获取板块数据

        :param symbol: 板块文件名
        :param group: 是否分组
        :return: 板块数据 DataFrame, 未找到返回 None
        """
        # from mootdx.block import BlockParse
        from mootdx.parse import BaseParse

        parse = BaseParse(tdxdir=self.tdxdir)
        return parse.parse(symbol=symbol, group=group, **kwargs)

    @staticmethod
    def _daily_reader():
        from tdxpy.reader import TdxDailyBarReader

        return TdxDailyBarReader()


class ExtReader(ReaderBase):
    """扩展市场数据读取类"""

    def __init__(self, tdxdir=None):
        super().__init__(tdxdir=tdxdir)

    def daily(self, symbol=None):
        """获取日线数据

        :param symbol: 股票代码
        :return: 日线数据 DataFrame, 未找到返回 None
        """
        filename = self.find_path(symbol=symbol, subdir='lday', suffix='day')

        if filename is None:
            return None

        from tdxpy.reader import TdxExHqDailyBarReader

        return TdxExHqDailyBarReader().get_df(filename)

    def minute(self, symbol=None):
        """获取分钟线数据

        :param symbol: 股票代码
        :return: 分钟线数据 DataFrame, 未找到返回 None
        """
        filename = self.find_path(symbol=symbol, subdir='minline', suffix=['lc1', '1'])

        if filename is None:
            return None

        from tdxpy.reader import TdxLCMinBarReader

        return TdxLCMinBarReader().get_df(filename)

    def fzline(self, symbol=None):
        """获取五分钟线数据

        :param symbol: 股票代码
        :return: 五分钟线数据 DataFrame, 未找到返回 None
        """
        filename = self.find_path(symbol=symbol, subdir='fzline', suffix=['lc5', '5'])

        if filename is None:
            return None

        from tdxpy.reader import TdxLCMinBarReader

        return TdxLCMinBarReader().get_df(filename)


class Reader(object):
    """数据读取工厂方法类"""

    @staticmethod
    def factory(market='std', **kwargs):
        """创建数据读取器

        :param market: 市场类型, std: 标准股票市场, ext: 扩展市场
        :param kwargs: 初始化参数
        :return: 数据读取器实例
        """
        if market == 'ext':
            return ExtReader(**kwargs)

        return StdReader(**kwargs)

# -*- coding: utf-8 -*-
from pathlib import Path

from mootdx.financial.financial import Financial, FinancialList, FinancialReader
from mootdx.logger import logger
from mootdx.utils import md5sum


class Affair(object):
    """财务数据处理类"""

    @staticmethod
    def parse(downdir='.', filename=None, **kwargs):
        """解析财务数据

        :param downdir: 下载目录
        :param filename: 文件名, 为空时解析目录下全部文件
        :return: 解析后的 DataFrame, 未找到返回 None
        """
        if filename:
            filepath = Path(downdir, filename)

            if not filepath.exists():
                logger.warning(f'文件不存在: {filepath}')
                return None

            return FinancialReader.to_data(str(filepath), **kwargs)

        # 解析目录下全部财务文件
        results = []
        downdir = Path(downdir)

        for filepath in sorted(downdir.glob('*.zip')) + sorted(downdir.glob('*.dat')):
            try:
                data = FinancialReader.to_data(str(filepath), **kwargs)

                if data is not None:
                    results.append(data)
            except Exception as e:  # noqa
                logger.warning(f'解析文件失败 {filepath}: {e}')

        if not results:
            return None

        import pandas as pd

        return pd.concat(results, ignore_index=True)

    @staticmethod
    def files():
        """获取财务文件列表

        :return: 文件信息列表, 每项包含 filename, hash, filesize 字段
        """
        financial = FinancialList()

        try:
            return financial.parse()
        except Exception as e:  # noqa
            logger.warning(f'获取财务文件列表失败: {e}')
            return []

    @staticmethod
    def fetch(downdir: str = None, filename: str = None):  # noqa
        """下载财务文件

        :param downdir: 下载目录
        :param filename: 文件名, 为空时下载全部文件
        :return: 是否下载成功
        """
        downdir = downdir or '.'

        if filename:
            return Affair._fetch_one(downdir=downdir, filename=filename)

        # 下载全部文件
        files = Affair.files()
        success = True

        for item in files:
            if not Affair._fetch_one(downdir=downdir, filename=item['filename'], filehash=item.get('hash')):
                success = False

        return success

    @staticmethod
    def _fetch_one(downdir, filename, filehash=None):
        """下载单个财务文件并校验"""
        financial = Financial()

        try:
            content, filepath = financial.content(downdir=downdir, filename=filename)
        except Exception as e:  # noqa
            logger.warning(f'下载文件失败 {filename}: {e}')
            return False

        if filepath is None:
            return False

        if filehash:
            local_hash = md5sum(filepath)

            if local_hash and local_hash.lower() != str(filehash).lower():
                logger.warning(f'文件校验失败 {filename}: {local_hash} != {filehash}')
                return False

        return True

# -*- coding: utf-8 -*-
import numpy as np
import pandas as pd

from mootdx.logger import logger


def _fetch_xdxr(collections=None):
    """获取除权除息数据

    :param collections: 除权除息数据集合
    :return: 除权除息数据 DataFrame
    """
    if collections is None:
        return pd.DataFrame()

    if isinstance(collections, pd.DataFrame):
        return collections

    from mootdx.utils import to_data

    return to_data(collections)


def factor_reversion(symbol: str, method: str = 'qfq', raw: pd.DataFrame = None) -> pd.DataFrame:
    """单只股票的复权处理

    :param symbol: 股票代码
    :param method: 复权方法 (qfq: 前复权, hfq: 后复权)
    :param raw: 原始数据
    :return: 复权后的数据 DataFrame
    """
    if raw is None or raw.empty:
        return raw

    try:
        from mootdx.utils.adjust import get_xdxr

        xdxr = get_xdxr(symbol)
    except Exception as e:  # noqa
        logger.warning(f'获取除权除息数据失败: {e}')
        return raw

    if xdxr is None or (hasattr(xdxr, 'empty') and xdxr.empty):
        return raw

    return reversion(symbol=symbol, stock_data=raw, xdxr=xdxr, type_='01' if method == 'qfq' else '02')


def etf_reversion(data, xdxr, adjust='01'):
    """ETF 复权处理

    :param data: 待复权数据
    :param xdxr: 除权除息数据
    :param adjust: 复权类型 (01: 前复权, 02: 后复权)
    :return: 复权后的数据 DataFrame
    """
    if data is None or data.empty or xdxr is None:
        return data

    xdxr = _fetch_xdxr(xdxr)

    if xdxr.empty:
        return data

    return _apply_reversion(data, xdxr, adjust)


def baoli_qfq(df, xdxr):
    """保利前复权处理

    :param df: 待复权数据
    :param xdxr: 除权除息数据
    :return: 复权后的数据 DataFrame
    """
    if df is None or df.empty or xdxr is None:
        return df

    xdxr = _fetch_xdxr(xdxr)

    if xdxr.empty:
        return df

    return _apply_reversion(df, xdxr, '01')


def _normalize_xdxr(xdxr):
    """标准化除权除息数据"""
    xdxr = xdxr.copy()

    if 'date' not in xdxr.columns:
        xdxr = xdxr.reset_index()

    xdxr['date'] = pd.to_datetime(xdxr['date'], errors='coerce')

    for col in ('fenhong', 'songzhuangu', 'peigu', 'peigujia', 'fenshu'):
        if col not in xdxr.columns:
            xdxr[col] = 0.0
        xdxr[col] = pd.to_numeric(xdxr[col], errors='coerce').fillna(0.0)

    return xdxr.sort_values('date')


def _apply_reversion(data, xdxr, adjust='01'):
    """应用复权计算 (前复权 01 / 后复权 02)"""
    data = data.copy()
    xdxr = _normalize_xdxr(xdxr)

    if 'date' in data.columns:
        dates = pd.to_datetime(data['date'], errors='coerce')
    else:
        dates = pd.to_datetime(data.index, errors='coerce')

    price_cols = [c for c in ('open', 'high', 'low', 'close') if c in data.columns]

    if not price_cols:
        return data

    factors = pd.Series(1.0, index=data.index)

    closes = pd.to_numeric(data['close'], errors='coerce')

    for _, row in xdxr.iterrows():
        event_date = row['date']

        # 除权事件: 每10股分红 fenhong, 送转 songzhuangu 股, 配股 peigu 股(配股价 peigujia)
        fenhong = row['fenhong'] / 10.0
        songgu = (row['songzhuangu'] + row.get('fenshu', 0.0)) / 10.0
        peigu = row['peigu'] / 10.0
        peigujia = row['peigujia']

        mask = dates < event_date
        before = closes[mask & dates.notna()]

        if before.empty:
            continue

        pre_close = float(before.iloc[-1]) if len(before) else 0.0

        if pre_close <= 0:
            continue

        # 单次除权因子
        factor = (pre_close - fenhong - peigujia * peigu) / (pre_close * (1 + songgu + peigu))

        if factor <= 0 or not np.isfinite(factor):
            continue

        if adjust in ('01', 'qfq'):
            factors[mask] = factors[mask] * factor
        else:
            factors[~mask & dates.notna()] = factors[~mask & dates.notna()] / factor

    for col in price_cols:
        data[col] = pd.to_numeric(data[col], errors='coerce') * factors

    if 'vol' in data.columns:
        data['vol'] = pd.to_numeric(data['vol'], errors='coerce') / factors.replace(0, np.nan)
        data['vol'] = data['vol'].fillna(0)

    return data


def reversion(symbol, stock_data, xdxr, type_='01'):
    """复权处理入口

    :param symbol: 股票代码
    :param stock_data: 股票数据
    :param xdxr: 除权除息数据
    :param type_: 复权类型 (01: 前复权, 02: 后复权)
    :return: 复权后的数据 DataFrame
    """
    if xdxr is None:
        try:
            from mootdx.utils.adjust import get_xdxr

            xdxr = get_xdxr(symbol)
        except Exception as e:  # noqa
            logger.warning(f'获取除权除息数据失败: {e}')
            xdxr = None

    if xdxr is None or (hasattr(xdxr, 'empty') and xdxr.empty):
        return stock_data

    xdxr = _fetch_xdxr(xdxr)

    if xdxr.empty:
        return stock_data

    return _apply_reversion(stock_data, xdxr, type_)

