import time

import pandas as pd

from mootdx.cache import file_cache, lru_cache
from mootdx.utils import get_config_path
from mootdx.utils.timer import timeit


def test_file_cache(tmp_path):
    cache_file = tmp_path / 'test.plk'
    calls = []

    @file_cache(filepath=cache_file, refresh_time=3600)
    def cached_function():
        calls.append(1)
        return pd.DataFrame({'data': ['test'], 'timestamp': [time.time()]})

    result1 = cached_function()
    result2 = cached_function()

    assert result1 is not None
    assert result1.equals(result2)
    assert len(calls) == 1


def test_lru_cache():
    @timeit
    @lru_cache(seconds=100, maxsize=None)
    def sample_function() -> pd.DataFrame:
        """Sample function that returns a constant DataFrame, for testing purpose."""
        return pd.DataFrame({'a': [1, 2, 3]})

    result1 = sample_function()
    result2 = sample_function()

    assert result1 is not None
    assert result1.equals(result2)

