import pytest

from mootdx.utils import demjson


class TestDecode:
    def test_object(self):
        assert demjson.decode('{"a": 1}') == {'a': 1}

    def test_array(self):
        assert demjson.decode('[1, 2, 3]') == [1, 2, 3]

    def test_nested(self):
        result = demjson.decode('{"a": [1, {"b": "x"}], "c": true, "d": null}')
        assert result == {'a': [1, {'b': 'x'}], 'c': True, 'd': None}

    def test_single_quotes(self):
        assert demjson.decode("{'a': 'b'}") == {'a': 'b'}

    def test_identifier_keys(self):
        assert demjson.decode('{a: 1, b: 2}') == {'a': 1, 'b': 2}

    def test_hex_number(self):
        assert demjson.decode('0x1f') == 31

    def test_non_numbers(self):
        result = demjson.decode('[NaN, Infinity, -Infinity]')
        assert result[0] != result[0]  # NaN
        assert result[1] == float('inf')
        assert result[2] == float('-inf')

    def test_undefined(self):
        assert demjson.decode('undefined') is demjson.undefined

    def test_comments(self):
        assert demjson.decode('{/* comment */ "a": 1 // line\n}') == {'a': 1}

    def test_trailing_comma(self):
        assert demjson.decode('[1, 2,]') == [1, 2]

    def test_invalid(self):
        with pytest.raises(demjson.JSONDecodeError):
            demjson.decode('{invalid')


class TestEncode:
